import * as THREE from 'three';

function canvas(size = 512) {
  const c = document.createElement('canvas');
  c.width = c.height = size;
  return [c, c.getContext('2d')];
}

function noise(ctx, size, amount = 12, alpha = 0.16) {
  const img = ctx.getImageData(0, 0, size, size);
  const d = img.data;
  for (let i = 0; i < d.length; i += 4) {
    const n = (Math.random() - 0.5) * amount;
    d[i] = Math.max(0, Math.min(255, d[i] + n));
    d[i + 1] = Math.max(0, Math.min(255, d[i + 1] + n));
    d[i + 2] = Math.max(0, Math.min(255, d[i + 2] + n));
  }
  ctx.putImageData(img, 0, 0);
  ctx.globalAlpha = alpha;
  ctx.globalAlpha = 1;
}

function finish(c, repeat = 1) {
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.repeat.set(repeat, repeat);
  t.anisotropy = 4;
  return t;
}

export function floorTexture() {
  const S = 512;
  const [c, ctx] = canvas(S);
  ctx.fillStyle = '#0b0d17';
  ctx.fillRect(0, 0, S, S);
  // large plates
  const cells = 4;
  const cs = S / cells;
  for (let y = 0; y < cells; y++) {
    for (let x = 0; x < cells; x++) {
      const v = 14 + Math.random() * 8;
      ctx.fillStyle = `rgb(${v},${v + 3},${v + 10})`;
      ctx.fillRect(x * cs + 3, y * cs + 3, cs - 6, cs - 6);
    }
  }
  // seams
  ctx.strokeStyle = 'rgba(0,0,0,.75)';
  ctx.lineWidth = 5;
  for (let i = 0; i <= cells; i++) {
    ctx.beginPath(); ctx.moveTo(i * cs, 0); ctx.lineTo(i * cs, S); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(0, i * cs); ctx.lineTo(S, i * cs); ctx.stroke();
  }
  // inner panel bevels
  ctx.strokeStyle = 'rgba(120,190,230,.12)';
  ctx.lineWidth = 1;
  for (let y = 0; y < cells; y++) {
    for (let x = 0; x < cells; x++) {
      ctx.strokeRect(x * cs + 10, y * cs + 10, cs - 20, cs - 20);
    }
  }
  // cyan service lines
  ctx.strokeStyle = 'rgba(45,190,215,.5)';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(0, cs * 1.5); ctx.lineTo(cs * 1.1, cs * 1.5); ctx.lineTo(cs * 1.1, cs * 2.8); ctx.lineTo(S, cs * 2.8);
  ctx.stroke();
  ctx.fillStyle = 'rgba(255,46,138,.28)';
  ctx.fillRect(cs * 2.1, 8, 3, cs - 16);
  // bolts
  ctx.fillStyle = 'rgba(160,200,220,.25)';
  for (let y = 0; y < cells; y++) for (let x = 0; x < cells; x++) {
    for (const [bx, by] of [[18, 18], [cs - 18, 18], [18, cs - 18], [cs - 18, cs - 18]]) {
      ctx.beginPath(); ctx.arc(x * cs + bx, y * cs + by, 2, 0, 7); ctx.fill();
    }
  }
  noise(ctx, S, 20, 0.1);
  return finish(c, 1);
}

export function wallTexture() {
  const S = 512;
  const [c, ctx] = canvas(S);
  ctx.fillStyle = '#0a0c16';
  ctx.fillRect(0, 0, S, S);
  const plank = S / 4;
  for (let i = 0; i < 4; i++) {
    const g = ctx.createLinearGradient(i * plank, 0, (i + 1) * plank, 0);
    g.addColorStop(0, '#111522');
    g.addColorStop(0.5, '#171d2e');
    g.addColorStop(1, '#0c0f1a');
    ctx.fillStyle = g;
    ctx.fillRect(i * plank + 4, 0, plank - 8, S);
  }
  ctx.strokeStyle = 'rgba(0,0,0,.7)';
  ctx.lineWidth = 6;
  for (let i = 0; i <= 4; i++) { ctx.beginPath(); ctx.moveTo(i * plank, 0); ctx.lineTo(i * plank, S); ctx.stroke(); }
  // horizontal ribs
  for (let y = 40; y < S; y += 110) {
    ctx.fillStyle = 'rgba(63,233,255,.07)';
    ctx.fillRect(0, y, S, 4);
    ctx.fillStyle = 'rgba(0,0,0,.4)';
    ctx.fillRect(0, y + 4, S, 2);
  }
  // emissive strip marks
  ctx.fillStyle = 'rgba(255,46,138,.4)';
  ctx.fillRect(0, S * 0.62, S, 2);
  ctx.fillStyle = 'rgba(63,233,255,.25)';
  ctx.fillRect(plank * 0.5, 0, 2, S);
  noise(ctx, S, 26, 0.12);
  return finish(c, 1);
}

export function hazardTexture() {
  const S = 256;
  const [c, ctx] = canvas(S);
  ctx.fillStyle = '#14100a';
  ctx.fillRect(0, 0, S, S);
  ctx.save();
  ctx.translate(S / 2, S / 2);
  ctx.rotate(-0.6);
  ctx.fillStyle = '#ffb02e';
  for (let i = -8; i < 10; i++) ctx.fillRect(i * 46, -S, 20, S * 2);
  ctx.restore();
  ctx.globalAlpha = 0.18;
  noise(ctx, S, 30, 0.1);
  ctx.globalAlpha = 1;
  const t = finish(c, 1);
  t.repeat.set(2, 1);
  return t;
}

export function glowTexture(inner = 'rgba(255,255,255,1)', mid = 'rgba(120,240,255,.5)', outer = 'rgba(40,180,255,0)') {
  const S = 128;
  const [c, ctx] = canvas(S);
  const g = ctx.createRadialGradient(S / 2, S / 2, 0, S / 2, S / 2, S / 2);
  g.addColorStop(0, inner);
  g.addColorStop(0.25, mid);
  g.addColorStop(1, outer);
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, S, S);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

export function planetTexture() {
  const W = 1024, H = 512;
  const c = document.createElement('canvas');
  c.width = W; c.height = H;
  const ctx = c.getContext('2d');
  const bands = [
    ['#29133f', '#3b1b5f', '#1a0d2d'],
    ['#5a1e52', '#8c2f6d', '#3a133f'],
    ['#b94a5c', '#e27b63', '#7c2f46'],
    ['#2b1a4d', '#4d2a6e', '#1c1038'],
    ['#c96b4f', '#f0a06a', '#8a3d43'],
    ['#3c1b5b', '#6a2c7e', '#241040'],
    ['#7e2a5c', '#b84a72', '#4c1a42'],
    ['#1c1238', '#352154', '#130a26'],
  ];
  let y = 0;
  let i = 0;
  while (y < H) {
    const h = 18 + Math.random() * 46;
    const [a, b, d] = bands[i % bands.length];
    const g = ctx.createLinearGradient(0, y, 0, y + h);
    g.addColorStop(0, a); g.addColorStop(0.5, b); g.addColorStop(1, d);
    ctx.fillStyle = g;
    ctx.fillRect(0, y, W, h + 1);
    // swirl detail
    ctx.globalAlpha = 0.18;
    ctx.strokeStyle = i % 2 ? '#ffd0b0' : '#7ce8ff';
    ctx.lineWidth = 2;
    for (let k = 0; k < 3; k++) {
      ctx.beginPath();
      const yy = y + Math.random() * h;
      ctx.moveTo(0, yy);
      for (let x = 0; x <= W; x += 32) ctx.lineTo(x, yy + Math.sin(x * 0.02 + i) * 6);
      ctx.stroke();
    }
    ctx.globalAlpha = 1;
    y += h;
    i++;
  }
  // storm eye
  const cx = W * 0.62, cy = H * 0.44;
  const rg = ctx.createRadialGradient(cx, cy, 4, cx, cy, 56);
  rg.addColorStop(0, 'rgba(255,180,140,.5)');
  rg.addColorStop(0.5, 'rgba(255,120,90,.2)');
  rg.addColorStop(1, 'rgba(255,80,80,0)');
  ctx.fillStyle = rg;
  ctx.beginPath(); ctx.ellipse(cx, cy, 70, 26, 0.1, 0, 7); ctx.fill();
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  t.wrapS = THREE.RepeatWrapping;
  return t;
}

export function padTexture() {
  const S = 256;
  const [c, ctx] = canvas(S);
  ctx.clearRect(0, 0, S, S);
  ctx.strokeStyle = 'rgba(63,233,255,.85)';
  ctx.lineWidth = 3;
  for (let r = 30; r < 120; r += 26) {
    ctx.beginPath(); ctx.arc(S / 2, S / 2, r, 0, 7); ctx.stroke();
  }
  ctx.fillStyle = 'rgba(63,233,255,.22)';
  ctx.beginPath(); ctx.arc(S / 2, S / 2, 118, 0, 7); ctx.fill();
  ctx.fillStyle = 'rgba(160,250,255,.95)';
  for (let i = 0; i < 3; i++) {
    const y = 70 + i * 42;
    ctx.beginPath();
    ctx.moveTo(S / 2 - 34, y); ctx.lineTo(S / 2, y - 20); ctx.lineTo(S / 2 + 34, y);
    ctx.lineTo(S / 2 + 34, y + 12); ctx.lineTo(S / 2, y - 8); ctx.lineTo(S / 2 - 34, y + 12);
    ctx.closePath(); ctx.fill();
  }
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

export function hologramTexture(title = 'VOID', sub = 'ARENA 04') {
  const W = 512, H = 256;
  const c = document.createElement('canvas');
  c.width = W; c.height = H;
  const ctx = c.getContext('2d');
  ctx.clearRect(0, 0, W, H);
  ctx.strokeStyle = 'rgba(63,233,255,.45)';
  ctx.lineWidth = 2;
  ctx.strokeRect(10, 10, W - 20, H - 20);
  ctx.fillStyle = 'rgba(63,233,255,.12)';
  ctx.fillRect(10, 10, W - 20, H - 20);
  ctx.font = '900 88px Orbitron, Arial';
  ctx.textAlign = 'center';
  ctx.fillStyle = '#bff8ff';
  ctx.shadowColor = '#3fe9ff';
  ctx.shadowBlur = 22;
  ctx.fillText(title, W / 2, 118);
  ctx.font = '600 22px Rajdhani, Arial';
  ctx.fillStyle = '#ff7bb0';
  ctx.shadowColor = '#ff2e8a';
  ctx.fillText(sub, W / 2, 165);
  ctx.shadowBlur = 0;
  ctx.strokeStyle = 'rgba(255,255,255,.2)';
  ctx.beginPath(); ctx.moveTo(60, 190); ctx.lineTo(W - 60, 190); ctx.stroke();
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

export function nameTexture(name, color = '#cfeaff') {
  const W = 256, H = 64;
  const c = document.createElement('canvas');
  c.width = W; c.height = H;
  const ctx = c.getContext('2d');
  ctx.clearRect(0, 0, W, H);
  ctx.font = '700 28px Orbitron, Arial';
  ctx.textAlign = 'center';
  ctx.fillStyle = 'rgba(0,0,0,.45)';
  ctx.fillRect(0, 14, W, 36);
  ctx.fillStyle = color;
  ctx.shadowColor = color;
  ctx.shadowBlur = 10;
  ctx.fillText(name, W / 2, 41);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

// Procedural WebAudio soundtrack + weapon SFX. No external assets.
export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.sfx = null;
    this.music = null;
    this.muted = localStorage.getItem('tribes_muted') === '1';
    this.jetGain = null;
    this.jetFilter = null;
    this.step = 0;
    this.nextNote = 0;
    this.intensity = 0.35;
    this.running = false;
    this.musicOn = true;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    const ctx = this.ctx = new AC();
    const comp = ctx.createDynamicsCompressor();
    comp.threshold.value = -16;
    comp.knee.value = 18;
    comp.ratio.value = 5;
    comp.attack.value = 0.004;
    comp.release.value = 0.22;
    this.master = ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.55;
    this.sfx = ctx.createGain();
    this.sfx.gain.value = 0.85;
    this.music = ctx.createGain();
    this.music.gain.value = 0.3;
    this.sfx.connect(comp);
    this.music.connect(comp);
    comp.connect(this.master);
    this.master.connect(ctx.destination);

    // noise buffer
    const len = ctx.sampleRate * 2;
    const buf = ctx.createBuffer(1, len, ctx.sampleRate);
    const d = buf.getChannelData(0);
    for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
    this.noiseBuf = buf;

    // jetpack loop
    const src = ctx.createBufferSource();
    src.buffer = buf;
    src.loop = true;
    const f = ctx.createBiquadFilter();
    f.type = 'bandpass';
    f.frequency.value = 460;
    f.Q.value = 0.8;
    const g = ctx.createGain();
    g.gain.value = 0;
    src.connect(f); f.connect(g); g.connect(this.sfx);
    src.start();
    this.jetGain = g;
    this.jetFilter = f;

    // menu ambient pad
    this.startMusic();
    this.nextNote = ctx.currentTime + 0.2;
    this.running = true;
  }

  setMuted(m) {
    this.muted = m;
    localStorage.setItem('tribes_muted', m ? '1' : '0');
    if (this.master) this.master.gain.setTargetAtTime(m ? 0 : 0.55, this.ctx.currentTime, 0.08);
  }

  setJet(on, fuel = 0) {
    if (!this.jetGain) return;
    const t = this.ctx.currentTime;
    this.jetGain.gain.setTargetAtTime(on ? 0.16 + 0.1 * fuel : 0, t, 0.055);
    if (on) this.jetFilter.frequency.setTargetAtTime(600 + 500 * fuel + Math.sin(t * 38) * 80, t, 0.06);
  }

  tone({ f = 440, to = null, dur = 0.15, type = 'sine', vol = 0.2, delay = 0, attack = 0.005, filter = null, bus = null }) {
    if (!this.ctx || this.muted) return;
    const ctx = this.ctx;
    const t = ctx.currentTime + delay;
    const o = ctx.createOscillator();
    o.type = type;
    o.frequency.setValueAtTime(f, t);
    if (to) o.frequency.exponentialRampToValueAtTime(Math.max(20, to), t + dur);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0, t);
    g.gain.linearRampToValueAtTime(vol, t + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    let node = o;
    if (filter) {
      const bq = ctx.createBiquadFilter();
      bq.type = filter.type || 'lowpass';
      bq.frequency.setValueAtTime(filter.f || 1200, t);
      if (filter.to) bq.frequency.exponentialRampToValueAtTime(filter.to, t + dur);
      bq.Q.value = filter.q ?? 1;
      node.connect(bq); node = bq;
    }
    node.connect(g); g.connect(bus || this.sfx);
    o.start(t); o.stop(t + dur + 0.02);
  }

  noise({ dur = 0.2, vol = 0.25, freq = 1200, to = null, type = 'lowpass', q = 0.8, delay = 0, bus = null }) {
    if (!this.ctx || this.muted || !this.noiseBuf) return;
    const ctx = this.ctx;
    const t = ctx.currentTime + delay;
    const s = ctx.createBufferSource();
    s.buffer = this.noiseBuf;
    s.playbackRate.value = 1;
    const f = ctx.createBiquadFilter();
    f.type = type;
    f.frequency.setValueAtTime(freq, t);
    if (to) f.frequency.exponentialRampToValueAtTime(Math.max(30, to), t + dur);
    f.Q.value = q;
    const g = ctx.createGain();
    g.gain.setValueAtTime(vol, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    s.connect(f); f.connect(g); g.connect(bus || this.sfx);
    s.start(t, Math.random() * 1.2); s.stop(t + dur + 0.02);
  }

  ui() { this.tone({ f: 1400, to: 900, dur: 0.04, type: 'square', vol: 0.035 }); }
  uiBig() { this.tone({ f: 220, to: 660, dur: 0.16, type: 'sawtooth', vol: 0.08, filter: { f: 900, to: 3000 } }); }

  shotgun() {
    this.noise({ dur: 0.28, vol: 0.5, freq: 3200, to: 220, q: 0.5 });
    this.tone({ f: 130, to: 52, dur: 0.2, type: 'square', vol: 0.22, filter: { f: 900, to: 200 } });
    this.noise({ dur: 0.06, vol: 0.25, freq: 5000, type: 'highpass' });
  }

  rocket() {
    this.tone({ f: 300, to: 90, dur: 0.32, type: 'sawtooth', vol: 0.16, filter: { f: 1800, to: 300 } });
    this.noise({ dur: 0.42, vol: 0.26, freq: 1600, to: 240, type: 'bandpass', q: 0.6 });
    this.tone({ f: 70, to: 40, dur: 0.3, type: 'sine', vol: 0.2 });
  }

  rail() {
    this.tone({ f: 2400, to: 260, dur: 0.32, type: 'sawtooth', vol: 0.14, filter: { f: 5000, to: 500, q: 4 } });
    this.tone({ f: 900, to: 1800, dur: 0.12, type: 'sine', vol: 0.1 });
    this.noise({ dur: 0.24, vol: 0.15, freq: 7000, to: 900, type: 'highpass' });
  }

  spin() {
    this.tone({ f: 520, to: 1300, dur: 0.22, type: 'triangle', vol: 0.16, filter: { f: 600, to: 3200, q: 3 } });
    this.noise({ dur: 0.2, vol: 0.12, freq: 2600, to: 900, type: 'bandpass', q: 2 });
  }

  explosion(big = 1) {
    this.noise({ dur: 0.7 * big, vol: 0.6, freq: 900, to: 70, q: 0.5 });
    this.tone({ f: 110, to: 28, dur: 0.55 * big, type: 'sine', vol: 0.42 });
    this.tone({ f: 60, to: 24, dur: 0.7 * big, type: 'triangle', vol: 0.3 });
    this.noise({ dur: 0.09, vol: 0.4, freq: 5000, type: 'highpass' });
  }

  hit() {
    this.tone({ f: 1800, to: 1200, dur: 0.05, type: 'square', vol: 0.09 });
    this.noise({ dur: 0.05, vol: 0.1, freq: 3200, type: 'highpass' });
  }

  hitKill() {
    this.tone({ f: 880, to: 1320, dur: 0.14, type: 'square', vol: 0.1 });
    this.tone({ f: 1320, to: 1760, dur: 0.16, type: 'square', vol: 0.07, delay: 0.06 });
    this.noise({ dur: 0.2, vol: 0.14, freq: 2000, to: 400, q: 1 });
  }

  hurt() {
    this.tone({ f: 90, to: 45, dur: 0.22, type: 'sawtooth', vol: 0.28, filter: { f: 500, to: 160 } });
    this.noise({ dur: 0.16, vol: 0.16, freq: 700, to: 200 });
  }

  jump() { this.tone({ f: 240, to: 460, dur: 0.12, type: 'sine', vol: 0.08 }); }
  land() { this.noise({ dur: 0.12, vol: 0.14, freq: 420, to: 100 }); }
  pickup() {
    [660, 880, 1320].forEach((f, i) => this.tone({ f, dur: 0.16, type: 'triangle', vol: 0.08, delay: i * 0.055 }));
  }
  armor() {
    [330, 440, 660].forEach((f, i) => this.tone({ f, dur: 0.22, type: 'sine', vol: 0.09, delay: i * 0.04 }));
  }
  quad() {
    [110, 165, 220, 330, 440].forEach((f, i) => this.tone({ f, dur: 0.9, type: 'sawtooth', vol: 0.06, delay: i * 0.05, filter: { f: 1400, to: 3200 } }));
    this.tone({ f: 55, to: 110, dur: 1.2, type: 'sine', vol: 0.18 });
  }
  death() {
    this.tone({ f: 300, to: 40, dur: 0.9, type: 'sawtooth', vol: 0.18, filter: { f: 1200, to: 100 } });
    this.noise({ dur: 0.7, vol: 0.2, freq: 800, to: 80 });
  }
  spawn() {
    this.tone({ f: 180, to: 720, dur: 0.35, type: 'triangle', vol: 0.07 });
    this.noise({ dur: 0.3, vol: 0.08, freq: 1200, to: 4200, type: 'bandpass', q: 1.6 });
  }
  pad() {
    this.tone({ f: 160, to: 900, dur: 0.35, type: 'sine', vol: 0.12 });
    this.noise({ dur: 0.4, vol: 0.14, freq: 600, to: 3200, type: 'bandpass', q: 1.4 });
  }
  tick() { this.tone({ f: 1100, dur: 0.03, type: 'square', vol: 0.04 }); }
  matchStart() {
    [220, 330, 440, 660].forEach((f, i) => this.tone({ f, dur: 0.34, type: 'sawtooth', vol: 0.09, delay: i * 0.11, filter: { f: 800, to: 2600 } }));
  }
  matchEnd(win) {
    const seq = win ? [330, 440, 550, 660, 880] : [330, 277, 220, 165];
    seq.forEach((f, i) => this.tone({ f, dur: 0.5, type: 'triangle', vol: 0.1, delay: i * 0.14 }));
  }

  startMusic() {
    if (!this.ctx || this.musicOn === false) return;
    this.musicOn = true;
    let padTimer = null;
    const ctx = this.ctx;
    // Dark drone pad
    const padGain = ctx.createGain();
    padGain.gain.value = 0.05;
    const padFilter = ctx.createBiquadFilter();
    padFilter.type = 'lowpass';
    padFilter.frequency.value = 380;
    padFilter.Q.value = 3;
    padGain.connect(padFilter); padFilter.connect(this.music);
    [55, 82.4, 110, 164.8].forEach((f, i) => {
      const o = ctx.createOscillator();
      o.type = i % 2 ? 'sawtooth' : 'triangle';
      o.frequency.value = f;
      o.detune.value = (i - 1.5) * 6;
      const g = ctx.createGain();
      g.gain.value = i % 2 ? 0.12 : 0.2;
      o.connect(g); g.connect(padGain);
      o.start();
    });
    // slow filter LFO
    const lfo = ctx.createOscillator();
    lfo.frequency.value = 0.045;
    const lg = ctx.createGain();
    lg.gain.value = 180;
    lfo.connect(lg); lg.connect(padFilter.frequency);
    lfo.start();
    this.padGain = padGain;
  }

  setIntensity(v) {
    this.intensity = Math.max(0, Math.min(1, v));
    if (this.padGain) this.padGain.gain.setTargetAtTime(0.035 + this.intensity * 0.03, this.ctx.currentTime, 0.5);
  }

  update() {
    if (!this.ctx || !this.running || this.muted) return;
    const ctx = this.ctx;
    const stepDur = 60 / 128 / 4; // 16th
    while (this.nextNote < ctx.currentTime + 0.15) {
      const t = this.nextNote;
      const s = this.step % 32;
      const bar = Math.floor(this.step / 32) % 4;
      const bassRoot = [55, 55, 49, 58.27][bar];
      const energy = this.intensity;

      // kick
      if (s % 8 === 0 || (s === 22 && energy > 0.5)) this.kick(t, 0.22);
      // snare on 2 & 4
      if (s % 16 === 8) this.snare(t, 0.13);
      // hats
      if (s % 2 === 0) this.hat(t, 0.018 + energy * 0.02, s % 4 === 0);
      // bass 16th pattern
      if ([0, 3, 6, 8, 11, 14].includes(s % 16)) {
        this.bass(t, bassRoot * (s % 8 === 6 ? 2 : 1), stepDur * 1.4, 0.13 + energy * 0.06);
      }
      // arp sparkle when intense
      if (energy > 0.35 && s % 2 === 0 && s % 8 !== 0) {
        const notes = [440, 523.25, 659.25, 783.99, 587.33, 698.46];
        const n = notes[(this.step / 2 | 0) % notes.length] * (bar === 2 ? 0.5 : 1);
        this.pluck(t, n, stepDur * 0.8, 0.035 + energy * 0.03);
      }
      this.step++;
      this.nextNote += stepDur;
    }
  }

  kick(t, vol) {
    if (!this.ctx) return;
    const ctx = this.ctx;
    const o = ctx.createOscillator();
    o.type = 'sine';
    o.frequency.setValueAtTime(130, t);
    o.frequency.exponentialRampToValueAtTime(38, t + 0.14);
    const g = ctx.createGain();
    g.gain.setValueAtTime(vol, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.22);
    o.connect(g); g.connect(this.music);
    o.start(t); o.stop(t + 0.24);
  }
  snare(t, vol) {
    const ctx = this.ctx;
    const s = ctx.createBufferSource(); s.buffer = this.noiseBuf;
    const f = ctx.createBiquadFilter(); f.type = 'bandpass'; f.frequency.value = 1800; f.Q.value = 1.2;
    const g = ctx.createGain(); g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.18);
    s.connect(f); f.connect(g); g.connect(this.music);
    s.start(t, Math.random()); s.stop(t + 0.2);
  }
  hat(t, vol, open) {
    const ctx = this.ctx;
    const s = ctx.createBufferSource(); s.buffer = this.noiseBuf;
    const f = ctx.createBiquadFilter(); f.type = 'highpass'; f.frequency.value = 6500;
    const g = ctx.createGain(); g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(0.0001, t + (open ? 0.1 : 0.04));
    s.connect(f); f.connect(g); g.connect(this.music);
    s.start(t, Math.random()); s.stop(t + 0.12);
  }
  bass(t, f, dur, vol) {
    const ctx = this.ctx;
    const o = ctx.createOscillator(); o.type = 'sawtooth'; o.frequency.value = f;
    const fl = ctx.createBiquadFilter(); fl.type = 'lowpass'; fl.frequency.setValueAtTime(520, t); fl.frequency.exponentialRampToValueAtTime(160, t + dur); fl.Q.value = 5;
    const g = ctx.createGain(); g.gain.setValueAtTime(0, t); g.gain.linearRampToValueAtTime(vol, t + 0.008); g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(fl); fl.connect(g); g.connect(this.music);
    o.start(t); o.stop(t + dur + 0.02);
  }
  pluck(t, f, dur, vol) {
    const ctx = this.ctx;
    const o = ctx.createOscillator(); o.type = 'triangle'; o.frequency.value = f;
    const g = ctx.createGain(); g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g); g.connect(this.music);
    o.start(t); o.stop(t + dur + 0.02);
  }
}

export class Input {
  constructor(canvas, { onPause, onLockChange, onWeapon, onScoreboard } = {}) {
    this.canvas = canvas;
    this.onPause = onPause;
    this.onLockChange = onLockChange;
    this.onWeapon = onWeapon;
    this.onScoreboard = onScoreboard;
    this.keys = new Set();
    this.pressed = new Set();
    this.look = { x: 0, y: 0 };
    this.mouseFire = false;
    this.locked = false;
    this.dragging = false;
    this.dragLast = { x: 0, y: 0 };
    this.enabled = false;
    this.sensitivity = 1;
    this.wheel = 0;
    this.touch = {
      active: false,
      moveX: 0, moveY: 0,
      lookX: 0, lookY: 0,
      fire: false, jet: false,
      lookId: null, lookLast: { x: 0, y: 0 },
      joyId: null,
    };
    this.bind();
  }

  get isTouch() {
    return matchMedia('(pointer: coarse)').matches || 'ontouchstart' in window;
  }

  bind() {
    window.addEventListener('keydown', (e) => {
      if (e.code === 'Tab') e.preventDefault();
      if (e.code === 'Space' && this.enabled) e.preventDefault();
      if (e.repeat) return;
      this.keys.add(e.code);
      this.pressed.add(e.code);
      if (e.code === 'Escape' && this.onPause) this.onPause();
    });
    window.addEventListener('keyup', (e) => this.keys.delete(e.code));
    window.addEventListener('blur', () => {
      this.keys.clear();
      this.mouseFire = false;
      this.touch.fire = false;
      this.touch.jet = false;
    });

    document.addEventListener('pointerlockchange', () => {
      this.locked = document.pointerLockElement === this.canvas;
      this.onLockChange?.(this.locked);
    });

    this.canvas.addEventListener('mousedown', (e) => {
      if (e.button !== 0 || !this.enabled) return;
      if (!this.locked && !this.isTouch) {
        this.requestLock();
        this.dragging = true;
        this.dragLast = { x: e.clientX, y: e.clientY };
        return;
      }
      this.mouseFire = true;
    });
    window.addEventListener('mouseup', (e) => {
      if (e.button === 0) { this.mouseFire = false; this.dragging = false; }
    });
    window.addEventListener('mousemove', (e) => {
      if (!this.enabled) return;
      if (this.locked) {
        this.look.x += e.movementX || 0;
        this.look.y += e.movementY || 0;
      } else if (this.dragging) {
        this.look.x += (e.clientX - this.dragLast.x) * 1.25;
        this.look.y += (e.clientY - this.dragLast.y) * 1.25;
        this.dragLast = { x: e.clientX, y: e.clientY };
      }
    });
    this.canvas.addEventListener('wheel', (e) => {
      if (!this.enabled) return;
      e.preventDefault();
      this.wheel += Math.sign(e.deltaY);
    }, { passive: false });

    // ---- Touch controls ----
    this.bindTouch();
  }

  bindTouch() {
    const stickZone = document.getElementById('stickZone');
    const knob = document.getElementById('stickKnob');
    const lookZone = document.getElementById('lookZone');
    const fire = document.getElementById('tFire');
    const jump = document.getElementById('tJump');
    const weapon = document.getElementById('tWeapon');
    const pause = document.getElementById('tPause');
    if (!stickZone) return;
    this.touch.active = true;

    const setKnob = (dx, dy) => {
      knob.style.transform = `translate(${dx * 42}px, ${dy * 42}px)`;
    };
    const onStick = (e) => {
      e.preventDefault();
      const r = stickZone.getBoundingClientRect();
      let dx = (e.clientX - (r.left + r.width / 2)) / (r.width * 0.42);
      let dy = (e.clientY - (r.top + r.height / 2)) / (r.height * 0.42);
      const len = Math.hypot(dx, dy);
      if (len > 1) { dx /= len; dy /= len; }
      const dead = 0.12;
      const mag = Math.hypot(dx, dy);
      if (mag < dead) { this.touch.moveX = 0; this.touch.moveY = 0; setKnob(dx, dy); return; }
      const s = (mag - dead) / (1 - dead);
      this.touch.moveX = (dx / mag) * s;
      this.touch.moveY = (dy / mag) * s;
      setKnob(dx, dy);
    };
    stickZone.addEventListener('pointerdown', (e) => {
      this.touch.joyId = e.pointerId;
      stickZone.setPointerCapture(e.pointerId);
      onStick(e);
    });
    stickZone.addEventListener('pointermove', (e) => {
      if (this.touch.joyId === e.pointerId) onStick(e);
    });
    const endStick = (e) => {
      if (this.touch.joyId !== e.pointerId) return;
      this.touch.joyId = null;
      this.touch.moveX = 0; this.touch.moveY = 0;
      setKnob(0, 0);
    };
    stickZone.addEventListener('pointerup', endStick);
    stickZone.addEventListener('pointercancel', endStick);

    lookZone.addEventListener('pointerdown', (e) => {
      this.touch.lookId = e.pointerId;
      this.touch.lookLast = { x: e.clientX, y: e.clientY };
      lookZone.setPointerCapture(e.pointerId);
    });
    lookZone.addEventListener('pointermove', (e) => {
      if (this.touch.lookId !== e.pointerId) return;
      this.touch.lookX += (e.clientX - this.touch.lookLast.x) * 1.9;
      this.touch.lookY += (e.clientY - this.touch.lookLast.y) * 1.9;
      this.touch.lookLast = { x: e.clientX, y: e.clientY };
    });
    const endLook = (e) => { if (this.touch.lookId === e.pointerId) this.touch.lookId = null; };
    lookZone.addEventListener('pointerup', endLook);
    lookZone.addEventListener('pointercancel', endLook);

    const holdBtn = (el, set) => {
      el.addEventListener('pointerdown', (e) => { e.preventDefault(); set(true); el.setPointerCapture(e.pointerId); });
      el.addEventListener('pointerup', () => set(false));
      el.addEventListener('pointercancel', () => set(false));
      el.addEventListener('pointerleave', () => set(false));
    };
    holdBtn(fire, (v) => { this.touch.fire = v; });
    holdBtn(jump, (v) => { this.touch.jet = v; if (v) this.pressed.add('Space'); });
    weapon.addEventListener('pointerdown', (e) => { e.preventDefault(); this.onWeapon?.(); });
    pause.addEventListener('pointerdown', (e) => { e.preventDefault(); this.onPause?.(); });
  }

  requestLock() {
    if (this.isTouch) return;
    try {
      const p = this.canvas.requestPointerLock?.();
      if (p?.catch) p.catch(() => {});
    } catch { /* pointer lock can be denied in embeds */ }
  }

  releaseLock() {
    if (document.pointerLockElement) document.exitPointerLock();
  }

  isDown(code) { return this.keys.has(code); }
  wasPressed(code) { return this.pressed.has(code); }

  consumeLook() {
    const x = this.look.x + this.touch.lookX;
    const y = this.look.y + this.touch.lookY;
    this.look.x = 0; this.look.y = 0;
    this.touch.lookX = 0; this.touch.lookY = 0;
    return { x, y };
  }

  consumeWheel() {
    const w = this.wheel;
    this.wheel = 0;
    return w;
  }

  get move() {
    let x = 0, z = 0;
    if (this.isDown('KeyD') || this.isDown('ArrowRight')) x += 1;
    if (this.isDown('KeyA') || this.isDown('ArrowLeft')) x -= 1;
    if (this.isDown('KeyW') || this.isDown('ArrowUp')) z += 1;
    if (this.isDown('KeyS') || this.isDown('ArrowDown')) z -= 1;
    x += this.touch.moveX;
    z -= this.touch.moveY;
    const len = Math.hypot(x, z);
    if (len > 1) { x /= len; z /= len; }
    return { x, z };
  }

  get firing() { return this.mouseFire || this.touch.fire; }

  get jetHeld() {
    return this.isDown('Space') || this.touch.jet;
  }

  endFrame() { this.pressed.clear(); }
}

import * as THREE from 'three';
import {
  floorTexture, wallTexture, hazardTexture, glowTexture, planetTexture,
  padTexture, hologramTexture
} from './textures.js';

const V = (x, y, z) => new THREE.Vector3(x, y, z);

export class World {
  constructor(scene) {
    this.scene = scene;
    this.colliders = [];
    this.meshes = [];
    this.decor = [];
    this.pickups = [];
    this.jumpPads = [];
    this.spawnPoints = [];
    this.navPoints = [];
    this.time = 0;
    this.raycaster = new THREE.Raycaster();
    this.buildMaterials();
    this.buildSky();
    this.buildLights();
    this.buildArena();
    this.buildPickups();
    this.buildPads();
    this.buildSpawns();
    this.buildDust();
  }

  buildMaterials() {
    const floorTex = floorTexture();
    floorTex.repeat.set(11, 11);
    const wallTex = wallTexture();
    wallTex.repeat.set(2, 2);
    const hazardTex = hazardTexture();

    this.mats = {
      floor: new THREE.MeshStandardMaterial({ map: floorTex, color: 0xb8c9dc, roughness: 0.58, metalness: 0.45 }),
      wall: new THREE.MeshStandardMaterial({ map: wallTex, color: 0xbfccdd, roughness: 0.52, metalness: 0.6 }),
      dark: new THREE.MeshStandardMaterial({ color: 0x151b2c, roughness: 0.48, metalness: 0.78 }),
      darker: new THREE.MeshStandardMaterial({ color: 0x0a0e18, roughness: 0.72, metalness: 0.55 }),
      hull: new THREE.MeshStandardMaterial({ color: 0x2b3550, roughness: 0.42, metalness: 0.82 }),
      hazard: new THREE.MeshStandardMaterial({ map: hazardTex, roughness: 0.7, metalness: 0.3 }),
      cyan: new THREE.MeshBasicMaterial({ color: 0x42eaff }),
      mag: new THREE.MeshBasicMaterial({ color: 0xff2e8a }),
      amber: new THREE.MeshBasicMaterial({ color: 0xffb02e }),
      green: new THREE.MeshBasicMaterial({ color: 0x51ffb0 }),
      white: new THREE.MeshBasicMaterial({ color: 0xdffbff }),
      holo: new THREE.MeshBasicMaterial({ color: 0x66eeff, transparent: true, opacity: 0.32, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false }),
      holoMag: new THREE.MeshBasicMaterial({ color: 0xff5fae, transparent: true, opacity: 0.4, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false }),
      glass: new THREE.MeshStandardMaterial({ color: 0x1a3450, emissive: 0x0b2b3a, emissiveIntensity: 0.6, roughness: 0.15, metalness: 0.9, transparent: true, opacity: 0.55 }),
      rock: new THREE.MeshStandardMaterial({ color: 0x171226, roughness: 0.95, metalness: 0.15 }),
    };
    this.glowCyan = glowTexture('rgba(220,255,255,1)', 'rgba(63,233,255,.45)', 'rgba(0,180,255,0)');
    this.glowMag = glowTexture('rgba(255,230,245,1)', 'rgba(255,46,138,.5)', 'rgba(255,0,80,0)');
    this.glowAmber = glowTexture('rgba(255,250,220,1)', 'rgba(255,176,46,.55)', 'rgba(255,100,0,0)');
  }

  buildSky() {
    const scene = this.scene;
    scene.fog = new THREE.FogExp2(0x08040f, 0.0085);
    scene.background = new THREE.Color(0x05020b);

    const skyGeo = new THREE.SphereGeometry(700, 32, 24);
    const skyMat = new THREE.ShaderMaterial({
      side: THREE.BackSide,
      depthWrite: false,
      fog: false,
      uniforms: {},
      vertexShader: `varying vec3 vDir; void main(){ vDir = normalize(position); gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`,
      fragmentShader: `
        varying vec3 vDir;
        float hash(vec2 p){ return fract(sin(dot(p, vec2(127.1,311.7))) * 43758.5453); }
        void main(){
          float h = vDir.y;
          vec3 zenith = vec3(0.014,0.006,0.045);
          vec3 upper = vec3(0.055,0.018,0.13);
          vec3 horizon = vec3(0.23,0.045,0.22);
          vec3 low = vec3(0.02,0.005,0.03);
          vec3 col = mix(low, horizon, smoothstep(-0.35,0.03,h));
          col = mix(col, upper, smoothstep(0.0,0.35,h));
          col = mix(col, zenith, smoothstep(0.3,0.9,h));
          // magenta bloom band near horizon
          col += vec3(0.32,0.03,0.16) * pow(max(0.0, 1.0 - abs(h - 0.015) * 5.0), 3.0) * 0.55;
          // faint nebula
          float n = hash(floor(vDir.xz*160.0)) * 0.5 + hash(floor(vDir.xz*57.0)) * 0.5;
          col += vec3(0.03,0.015,0.06) * n * smoothstep(-0.1,0.5,h);
          gl_FragColor = vec4(col, 1.0);
        }`
    });
    this.sky = new THREE.Mesh(skyGeo, skyMat);
    this.sky.frustumCulled = false;
    scene.add(this.sky);

    // stars
    const N = 1800;
    const pos = new Float32Array(N * 3);
    for (let i = 0; i < N; i++) {
      const u = Math.random() * 2 - 1;
      const th = Math.random() * Math.PI * 2;
      const r = 430 + Math.random() * 160;
      const s = Math.sqrt(1 - u * u);
      pos[i * 3] = Math.cos(th) * s * r;
      pos[i * 3 + 1] = u * r * 0.85 + 40;
      pos[i * 3 + 2] = Math.sin(th) * s * r;
    }
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    const stars = new THREE.Points(g, new THREE.PointsMaterial({
      color: 0xbfeaff, size: 1.6, sizeAttenuation: true, transparent: true, opacity: 0.9, fog: false, depthWrite: false,
      blending: THREE.AdditiveBlending
    }));
    scene.add(stars);

    // gas giant
    const planet = new THREE.Mesh(
      new THREE.SphereGeometry(110, 48, 32),
      new THREE.MeshBasicMaterial({ map: planetTexture(), fog: false })
    );
    planet.position.set(-260, 80, -430);
    scene.add(planet);

    const ringGeo = new THREE.RingGeometry(132, 226, 110);
    const ring = new THREE.Mesh(ringGeo, new THREE.MeshBasicMaterial({
      color: 0xd29ab4, transparent: true, opacity: 0.22, side: THREE.DoubleSide, fog: false, depthWrite: false
    }));
    ring.position.copy(planet.position);
    ring.rotation.set(1.32, 0.18, 0.35);
    scene.add(ring);

    const glow = new THREE.Sprite(new THREE.SpriteMaterial({
      map: this.glowMag, color: 0xff6a9e, transparent: true, opacity: 0.45, blending: THREE.AdditiveBlending, depthWrite: false, fog: false
    }));
    glow.position.set(-260, 80, -470);
    glow.scale.setScalar(420);
    scene.add(glow);

    // moons
    const moonMat = new THREE.MeshBasicMaterial({ color: 0xb6c9de, fog: false });
    for (const [x, y, z, r] of [[220, 120, -300, 12], [160, 30, 240, 7], [-120, 170, 200, 5]]) {
      const m = new THREE.Mesh(new THREE.IcosahedronGeometry(r, 1), moonMat);
      m.position.set(x, y, z);
      scene.add(m);
    }

    // drifting rocks around arena
    const rockGeos = [
      new THREE.IcosahedronGeometry(1, 0),
      new THREE.DodecahedronGeometry(1, 0),
      new THREE.OctahedronGeometry(1, 0),
    ];
    for (let i = 0; i < 14; i++) {
      const geo = rockGeos[i % rockGeos.length];
      const r = new THREE.Mesh(geo, this.mats.rock);
      const ang = (i / 14) * Math.PI * 2 + Math.random() * 0.4;
      const rad = 62 + Math.random() * 55;
      r.position.set(Math.cos(ang) * rad, -24 + Math.random() * 50, Math.sin(ang) * rad);
      const s = 2.5 + Math.random() * 7;
      r.scale.set(s * (0.7 + Math.random() * 0.7), s * (0.5 + Math.random() * 0.5), s * (0.7 + Math.random() * 0.6));
      r.rotation.set(Math.random() * 6, Math.random() * 6, Math.random() * 6);
      r.userData.spin = (Math.random() - 0.5) * 0.04;
      this.decor.push(r);
      scene.add(r);
    }

    // distant orbital debris / broken ring
    const debrisMat = new THREE.MeshBasicMaterial({ color: 0x2a3350, fog: false });
    for (let i = 0; i < 26; i++) {
      const d = new THREE.Mesh(new THREE.BoxGeometry(1, 1, 1), debrisMat);
      const a = Math.random() * Math.PI * 2;
      const rad = 140 + Math.random() * 120;
      d.position.set(Math.cos(a) * rad, -50 + Math.random() * 150, Math.sin(a) * rad);
      d.scale.set(1 + Math.random() * 9, 1 + Math.random() * 3, 1 + Math.random() * 8);
      d.rotation.set(Math.random() * 5, Math.random() * 5, Math.random() * 5);
      scene.add(d);
    }
  }

  buildLights() {
    const scene = this.scene;
    scene.add(new THREE.HemisphereLight(0x7b5cff, 0x140818, 1.35));

    const key = new THREE.DirectionalLight(0xffd9e8, 2.8);
    key.position.set(-38, 58, 26);
    key.castShadow = true;
    key.shadow.mapSize.set(2048, 2048);
    key.shadow.camera.left = -52;
    key.shadow.camera.right = 52;
    key.shadow.camera.top = 52;
    key.shadow.camera.bottom = -52;
    key.shadow.camera.near = 1;
    key.shadow.camera.far = 160;
    key.shadow.bias = -0.0008;
    key.shadow.normalBias = 0.03;
    scene.add(key);

    const rim = new THREE.DirectionalLight(0xff3f8f, 1.5);
    rim.position.set(40, 26, -44);
    scene.add(rim);

    const cyanFill = new THREE.DirectionalLight(0x3fe9ff, 0.7);
    cyanFill.position.set(30, 12, 30);
    scene.add(cyanFill);

    const pts = [
      [0, 10, 0, 0xffb02e, 210, 30],
      [25, 9, 0, 0x3fe9ff, 130, 26],
      [-25, 9, 0, 0xff2e8a, 130, 26],
      [0, 8, 26, 0xff2e8a, 90, 24],
      [0, 8, -26, 0x3fe9ff, 90, 24],
    ];
    this.lights = [];
    for (const [x, y, z, c, i, d] of pts) {
      const l = new THREE.PointLight(c, i, d, 2);
      l.position.set(x, y, z);
      scene.add(l);
      this.lights.push(l);
    }
  }

  box(x, y, z, w, h, d, mat, { solid = true, cast = true, receive = true, ray = true } = {}) {
    const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
    mesh.position.set(x, y, z);
    mesh.castShadow = cast;
    mesh.receiveShadow = receive;
    this.scene.add(mesh);
    if (solid) {
      this.colliders.push(new THREE.Box3(V(x - w / 2, y - h / 2, z - d / 2), V(x + w / 2, y + h / 2, z + d / 2)));
    }
    if (ray) this.meshes.push(mesh);
    return mesh;
  }

  trim(x, y, z, w, h, d, mat) {
    const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
    m.position.set(x, y, z);
    this.scene.add(m);
    this.decor.push(m);
    return m;
  }

  cyl(x, y, z, r, h, mat, { solid = false, seg = 32, cast = true } = {}) {
    const m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, h, seg), mat);
    m.position.set(x, y, z);
    m.castShadow = cast;
    m.receiveShadow = true;
    this.scene.add(m);
    if (solid) this.colliders.push(new THREE.Box3(V(x - r, y - h / 2, z - r), V(x + r, y + h / 2, z + r)));
    this.meshes.push(m);
    return m;
  }

  buildArena() {
    const M = this.mats;

    // main deck
    this.box(0, -1, 0, 74, 2, 74, M.floor, { cast: true });
    // understructure
    this.box(0, -2.4, 0, 66, 1.4, 66, M.darker, { cast: false });
    for (let i = -3; i <= 3; i++) {
      this.box(i * 10, -4.4, 0, 2.2, 2.8, 62, M.dark, { cast: false });
      this.box(0, -4.4, i * 10, 62, 2.8, 2.2, M.dark, { cast: false });
    }
    this.trim(0, -6.2, 0, 40, 1.2, 40, M.hull);
    // edge trims + hazard corners
    for (const s of [-1, 1]) {
      this.trim(0, 0.045, s * 36.8, 74, 0.09, 0.24, s > 0 ? M.mag : M.cyan);
      this.trim(s * 36.8, 0.045, 0, 0.24, 0.09, 74, s > 0 ? M.cyan : M.mag);
      for (let i = -3; i <= 3; i++) {
        this.trim(i * 9.5, 0.05, s * 33.5, 4.2, 0.08, 0.5, M.hazard);
        this.trim(s * 33.5, 0.05, i * 9.5, 0.5, 0.08, 4.2, M.hazard);
      }
    }
    // deck inset glow strips
    for (const s of [-1, 1]) {
      this.trim(s * 12, 0.03, 0, 0.12, 0.06, 46, M.cyan);
      this.trim(0, 0.03, s * 12, 46, 0.06, 0.12, M.mag);
    }

    // ---- central platform ----
    this.box(0, 3.85, 0, 15.4, 1.1, 15.4, M.hull);
    this.cyl(0, 4.0, 0, 8.2, 0.7, M.hull, { cast: true });
    this.cyl(0, 4.44, 0, 7.95, 0.14, M.dark, { cast: false, seg: 48 });
    // legs
    for (const [x, z] of [[-5.6, -5.6], [5.6, -5.6], [-5.6, 5.6], [5.6, 5.6]]) {
      this.box(x, 1.75, z, 1.5, 3.5, 1.5, M.dark);
      this.trim(x, 0.25, z, 1.9, 0.5, 1.9, M.cyan);
    }
    // platform rings
    const ring1 = new THREE.Mesh(new THREE.TorusGeometry(8.05, 0.075, 6, 64), M.cyan);
    ring1.rotation.x = Math.PI / 2; ring1.position.y = 4.46; this.scene.add(ring1); this.decor.push(ring1);
    const ring2 = new THREE.Mesh(new THREE.TorusGeometry(5.4, 0.05, 6, 64), M.mag);
    ring2.rotation.x = Math.PI / 2; ring2.position.y = 4.49; this.scene.add(ring2); this.decor.push(ring2);
    // staircases (+x and -x)
    for (const s of [-1, 1]) {
      const steps = 7;
      for (let i = 0; i < steps; i++) {
        const top = 4.44 * (i + 1) / steps;
        const x = s * (8.0 + (steps - i - 0.5) * 0.82);
        this.box(x, top / 2, 0, 0.82, top, 3.9, M.wall);
        this.trim(x, top + 0.015, 0, 0.82, 0.03, 3.9, M.cyan, { cast: false });
      }
      // side rails for stair
      for (let i = 0; i < steps; i += 2) {
        const top = 4.44 * (i + 1) / steps;
        const x = s * (8.0 + (steps - i - 0.5) * 0.82);
        this.trim(x, top + 0.45, 1.95, 0.6, 0.06, 0.06, M.cyan);
        this.trim(x, top + 0.45, -1.95, 0.6, 0.06, 0.06, M.cyan);
      }
    }
    // under-platform cover ring
    for (const [x, z, w, d] of [[0, -6.6, 7, 1.2], [0, 6.6, 7, 1.2], [-6.6, 0, 1.2, 7], [6.6, 0, 1.2, 7]]) {
      this.box(x, 1.1, z, w, 2.2, d, M.dark);
    }
    // central pedestal + emblem
    this.cyl(0, 4.62, 0, 1.5, 0.36, M.dark, { cast: false, seg: 24 });
    const emblem = new THREE.Mesh(new THREE.RingGeometry(1.0, 1.35, 6), M.amber);
    emblem.rotation.x = -Math.PI / 2; emblem.position.y = 4.82; this.scene.add(emblem); this.decor.push(emblem);

    // hologram above center
    const holoTex = hologramTexture('VOID', 'ARENA 04');
    this.holoMat = new THREE.MeshBasicMaterial({ map: holoTex, transparent: true, opacity: 0.7, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false });
    const holo = new THREE.Mesh(new THREE.PlaneGeometry(9, 4.5), this.holoMat);
    holo.position.set(0, 9.6, 0);
    this.scene.add(holo);
    this.holo = holo;
    const holoRing = new THREE.Mesh(new THREE.TorusGeometry(4.6, 0.05, 5, 48), M.cyan);
    holoRing.position.y = 9.6;
    this.scene.add(holoRing);
    this.holoRing = holoRing;

    // ---- side bastions ----
    for (const s of [-1, 1]) {
      this.box(s * 25, 2.8, 0, 11, 5.6, 11, M.wall);
      this.box(s * 25, 5.75, 0, 12, 0.3, 12, M.hull);
      this.trim(s * 25, 5.93, 0, 11.4, 0.06, 0.18, M.cyan);
      // vertical columns
      for (const zz of [-4.6, 4.6]) {
        this.box(s * 25 + (s > 0 ? 4.9 : -4.9), 2.8, zz, 0.55, 5.6, 0.55, M.dark);
        this.trim(s * 25 + (s > 0 ? 4.9 : -4.9), 3.1, zz, 0.62, 3.3, 0.08, s > 0 ? M.cyan : M.mag);
      }
      // roof cover
      this.box(s * 25, 6.4, -3.7, 3.4, 1.1, 1.1, M.dark);
      this.box(s * 25, 6.4, 3.7, 3.4, 1.1, 1.1, M.dark);
      this.trim(s * 25, 7.0, 0, 0.7, 0.6, 0.7, s > 0 ? M.cyan : M.mag);
      // side holo stripe
      this.trim(s * 19.42, 2.8, 0, 0.06, 5.0, 8.8, s > 0 ? M.mag : M.cyan, { cast: false });
      // ground glow base
      this.trim(s * 25, 0.06, 0, 12.6, 0.08, 0.35, s > 0 ? M.cyan : M.mag);
    }

    // ---- corner cover blocks ----
    for (const [x, z] of [[-17, -17], [17, -17], [-17, 17], [17, 17]]) {
      this.box(x, 1.6, z, 5.2, 3.2, 5.2, M.wall);
      this.box(x, 3.3, z, 5.4, 0.25, 5.4, M.dark);
      this.trim(x, 3.47, z, 5.0, 0.06, 0.16, (x * z > 0) ? M.cyan : M.mag);
      this.trim(x, 0.25, z - 2.62 * Math.sign(z || 1), 4.2, 0.4, 0.03, M.hazard, { cast: false });
      this.trim(x + 2.62 * Math.sign(x || 1), 0.25, z, 0.03, 0.4, 4.2, M.hazard, { cast: false });
      // corner light spike
      this.box(x + 2.4 * Math.sign(x || 1), 4.1, z + 2.4 * Math.sign(z || 1), 0.4, 1.6, 0.4, M.dark);
      this.trim(x + 2.4 * Math.sign(x || 1), 5.0, z + 2.4 * Math.sign(z || 1), 0.5, 0.1, 0.5, M.amber);
    }

    // ---- mid-field pillars ----
    for (const [x, z] of [[-10.5, -10.5], [10.5, -10.5], [-10.5, 10.5], [10.5, 10.5]]) {
      this.box(x, 2.5, z, 1.5, 5, 1.5, M.dark);
      this.trim(x, 5.05, z, 1.7, 0.12, 1.7, this.mats.cyan);
      this.trim(x, 0.15, z, 1.7, 0.3, 1.7, this.mats.mag);
    }

    // ---- outer lane walls ----
    for (const s of [-1, 1]) {
      this.box(-29, 1.15, s * 18, 1.3, 2.3, 9, M.wall);
      this.box(29, 1.15, s * 18, 1.3, 2.3, 9, M.wall);
      this.trim(-29, 2.35, s * 18, 1.4, 0.08, 9, s > 0 ? M.mag : M.cyan);
      this.trim(29, 2.35, s * 18, 1.4, 0.08, 9, s > 0 ? M.cyan : M.mag);
      // low barricades
      this.box(-13, 0.65, s * 26, 6.5, 1.3, 1.1, M.dark);
      this.box(13, 0.65, s * 26, 6.5, 1.3, 1.1, M.dark);
      this.trim(-13, 1.33, s * 26, 6.5, 0.05, 0.16, s > 0 ? M.cyan : M.mag);
      this.trim(13, 1.33, s * 26, 6.5, 0.05, 0.16, s > 0 ? M.mag : M.cyan);
    }

    // ---- entry arch (-z) ----
    const gateZ = -33.5;
    this.box(-10.5, 6.5, gateZ, 2.6, 13, 2.6, M.wall);
    this.box(10.5, 6.5, gateZ, 2.6, 13, 2.6, M.wall);
    this.box(0, 12.2, gateZ, 23.6, 2.4, 2.8, M.hull);
    this.trim(0, 11.05, gateZ + 1.42, 18, 0.18, 0.05, M.cyan);
    this.trim(-10.5, 3.2, gateZ + 1.32, 0.12, 9.4, 0.05, M.mag);
    this.trim(10.5, 3.2, gateZ + 1.32, 0.12, 9.4, 0.05, M.cyan);
    // gate sign
    const signTex = hologramTexture('TRIBES', 'VOID ARENA');
    const sign = new THREE.Mesh(new THREE.PlaneGeometry(9.5, 4.75), new THREE.MeshBasicMaterial({
      map: signTex, transparent: true, opacity: 0.85, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide
    }));
    sign.position.set(0, 9.4, gateZ + 1.5);
    this.scene.add(sign);
    this.sign = sign;
    // arch lights
    for (const x of [-10.5, 10.5]) {
      this.trim(x, 12.2, gateZ + 1.5, 0.25, 2.4, 0.08, x > 0 ? M.cyan : M.mag);
    }

    // ---- hanging banners on sides ----
    for (const [x, z, c] of [[-36, 14, 0], [-36, -14, 1], [36, 14, 1], [36, -14, 0]]) {
      const banner = this.box(x, 6.0, z, 0.25, 8.5, 5.4, M.dark, { solid: false, cast: false });
      const strip = this.trim(x + (x > 0 ? -0.14 : 0.14), 6.0, z, 0.02, 8.1, 0.18, c ? M.cyan : M.mag);
      this.trim(x, 10.3, z, 0.3, 0.3, 5.8, c ? M.cyan : M.mag, { cast: false });
    }

    // ---- floating support drones / lights ----
    for (let i = 0; i < 6; i++) {
      const a = (i / 6) * Math.PI * 2 + 0.25;
      const r = 41;
      const drone = new THREE.Group();
      const body = new THREE.Mesh(new THREE.BoxGeometry(1.3, 0.35, 0.7), M.dark);
      body.castShadow = true;
      const eye = new THREE.Mesh(new THREE.SphereGeometry(0.16, 8, 6), i % 2 ? M.mag : M.cyan);
      eye.position.z = 0.36;
      drone.add(body, eye);
      const spr = new THREE.Sprite(new THREE.SpriteMaterial({
        map: i % 2 ? this.glowMag : this.glowCyan, transparent: true, opacity: 0.7, blending: THREE.AdditiveBlending, depthWrite: false
      }));
      spr.scale.setScalar(2.4);
      drone.add(spr);
      drone.position.set(Math.cos(a) * r, 11 + (i % 3) * 3, Math.sin(a) * r);
      drone.userData = { a, r, baseY: drone.position.y, i };
      this.scene.add(drone);
      this.decor.push(drone);
      this.drones = this.drones || [];
      this.drones.push(drone);
    }

    // horizon arena spires (decor only)
    for (const [x, z, h] of [[-70, -80, 40], [80, -60, 30], [90, 60, 46], [-85, 70, 26]]) {
      this.box(x, h / 2 - 12, z, 8, h, 8, M.dark, { solid: false, cast: false });
      this.trim(x, h - 12, z, 9, 0.4, 9, M.cyan);
    }
  }

  buildPickups() {
    const defs = [
      ['quad', 0, 5.05, 0],
      ['mega', 0, 0.95, 0],
      ['health', -20, 0.95, 20],
      ['health', 20, 0.95, -20],
      ['health', 0, 0.95, 27],
      ['armor', 20, 0.95, 20],
      ['armor', -20, 0.95, -20],
      ['armor', 0, 0.95, -27],
      ['rockets', -18, 0.95, 0],
      ['rockets', 18, 0.95, 0],
      ['rails', 0, 0.95, 20],
      ['rails', 0, 0.95, -20],
    ];
    // pickups on bastion roofs
    defs.push(['rails', 25, 6.95, 0]);
    defs.push(['rockets', -25, 6.95, 0]);
    for (const [type, x, y, z] of defs) this.addPickup(type, V(x, y, z));
  }

  addPickup(type, pos) {
    const M = this.mats;
    const g = new THREE.Group();
    g.position.copy(pos);
    const spin = new THREE.Group();
    g.add(spin);
    let lightColor = 0x51ffb0;
    let lightScale = 2.1;
    let respawn = 18;
    let label = type;

    if (type === 'health') {
      const mat = new THREE.MeshBasicMaterial({ color: 0xff3b5c });
      const a = new THREE.Mesh(new THREE.BoxGeometry(0.95, 0.3, 0.3), mat);
      const b = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.95, 0.3), mat);
      spin.add(a, b);
      lightColor = 0xff3b5c;
    } else if (type === 'mega') {
      const mat = new THREE.MeshBasicMaterial({ color: 0x8affd0 });
      const a = new THREE.Mesh(new THREE.BoxGeometry(1.5, 0.45, 0.45), mat);
      const b = new THREE.Mesh(new THREE.BoxGeometry(0.45, 1.5, 0.45), mat);
      spin.add(a, b);
      const orb = new THREE.Mesh(new THREE.IcosahedronGeometry(0.62, 1), new THREE.MeshBasicMaterial({ color: 0x51ffb0, wireframe: true, transparent: true, opacity: 0.6 }));
      orb.scale.setScalar(1.5);
      spin.add(orb);
      lightColor = 0x51ffb0; lightScale = 3.4; respawn = 32;
    } else if (type === 'armor') {
      const m = new THREE.Mesh(new THREE.OctahedronGeometry(0.52, 0), new THREE.MeshStandardMaterial({ color: 0x58ffe0, emissive: 0x1a9a7a, emissiveIntensity: 2, metalness: 0.3, roughness: 0.25 }));
      m.scale.set(0.85, 1.25, 0.55);
      spin.add(m);
      const w = new THREE.Mesh(new THREE.OctahedronGeometry(0.56, 0), new THREE.MeshBasicMaterial({ color: 0xacfff0, wireframe: true, transparent: true, opacity: 0.55 }));
      w.scale.set(0.85, 1.25, 0.55);
      spin.add(w);
      lightColor = 0x51ffb0; lightScale = 2.4;
    } else if (type === 'rockets') {
      for (let i = -1; i <= 1; i++) {
        const m = new THREE.Mesh(new THREE.CylinderGeometry(0.1, 0.13, 0.85, 8), new THREE.MeshStandardMaterial({ color: 0xffb02e, emissive: 0xff6a00, emissiveIntensity: 1.4, roughness: 0.4, metalness: 0.6 }));
        m.position.set(i * 0.3, 0, 0);
        m.rotation.z = i * 0.2;
        spin.add(m);
        const tip = new THREE.Mesh(new THREE.ConeGeometry(0.13, 0.24, 8), new THREE.MeshBasicMaterial({ color: 0xffe0a0 }));
        tip.position.set(i * 0.3, 0.55, 0);
        spin.add(tip);
      }
      lightColor = 0xffb02e; respawn = 14;
    } else if (type === 'rails') {
      const m = new THREE.Mesh(new THREE.CylinderGeometry(0.18, 0.18, 1.15, 6), new THREE.MeshStandardMaterial({ color: 0x65f4ff, emissive: 0x22c7ff, emissiveIntensity: 2.4, metalness: 0.7, roughness: 0.2 }));
      spin.add(m);
      for (const yy of [-0.32, 0.32]) {
        const r = new THREE.Mesh(new THREE.TorusGeometry(0.25, 0.04, 5, 16), M.cyan);
        r.rotation.x = Math.PI / 2; r.position.y = yy; spin.add(r);
      }
      lightColor = 0x3fe9ff; respawn = 16;
    } else if (type === 'quad') {
      const mat = new THREE.MeshStandardMaterial({ color: 0xffc24d, emissive: 0xff6a00, emissiveIntensity: 2.5, metalness: 0.6, roughness: 0.22 });
      const core = new THREE.Mesh(new THREE.IcosahedronGeometry(0.85, 1), mat);
      spin.add(core);
      const w = new THREE.Mesh(new THREE.IcosahedronGeometry(0.9, 0), new THREE.MeshBasicMaterial({ color: 0xffe0a0, wireframe: true, transparent: true, opacity: 0.7 }));
      spin.add(w);
      for (let i = 0; i < 3; i++) {
        const ring = new THREE.Mesh(new THREE.TorusGeometry(1.25 + i * 0.24, 0.035, 5, 48), i === 1 ? M.mag : M.amber);
        ring.rotation.set(i * 0.9, i * 1.4, 0);
        spin.add(ring);
      }
      lightColor = 0xffb02e; lightScale = 4.4; respawn = 38; label = 'quad';
    }

    const glow = new THREE.Sprite(new THREE.SpriteMaterial({
      map: type === 'quad' || type === 'rockets' ? this.glowAmber : type === 'health' ? this.glowMag : this.glowCyan,
      transparent: true, opacity: 0.75, blending: THREE.AdditiveBlending, depthWrite: false
    }));
    glow.scale.setScalar(lightScale);
    g.add(glow);

    // ground ring
    const ring = new THREE.Mesh(new THREE.TorusGeometry(type === 'quad' ? 1.65 : 1.0, 0.045, 4, 32), new THREE.MeshBasicMaterial({
      color: lightColor, transparent: true, opacity: 0.55, blending: THREE.AdditiveBlending
    }));
    ring.rotation.x = Math.PI / 2;
    ring.position.y = -(pos.y - 0.08);
    g.add(ring);

    const light = new THREE.PointLight(lightColor, type === 'quad' ? 22 : 7, 7, 2);
    light.position.y = 0.6;
    g.add(light);

    this.scene.add(g);
    const pickup = {
      type, label, group: g, spin, glow, ring, light,
      position: pos.clone(), baseY: pos.y,
      active: true, timer: 0, respawn, phase: Math.random() * 6,
      bob: 0.16,
    };
    this.pickups.push(pickup);
    return pickup;
  }

  buildPads() {
    const defs = [
      { x: -14, z: 0, launch: V(-9.8, 20.5, 0), color: 0xff2e8a },
      { x: 14, z: 0, launch: V(9.8, 20.5, 0), color: 0x3fe9ff },
      { x: 0, z: 16, launch: V(0, 18.5, -8.2), color: 0x3fe9ff },
      { x: 0, z: -16, launch: V(0, 18.5, 8.2), color: 0xff2e8a },
    ];
    for (const d of defs) {
      const g = new THREE.Group();
      g.position.set(d.x, 0.02, d.z);
      const base = new THREE.Mesh(new THREE.CylinderGeometry(2.35, 2.55, 0.22, 32), this.mats.dark);
      base.receiveShadow = true; base.position.y = 0.11;
      const topMat = new THREE.MeshBasicMaterial({
        map: padTexture(), transparent: true, opacity: 0.95, blending: THREE.AdditiveBlending, depthWrite: false,
        color: d.color
      });
      const top = new THREE.Mesh(new THREE.CircleGeometry(2.15, 40), topMat);
      top.rotation.x = -Math.PI / 2; top.position.y = 0.235;
      const rim = new THREE.Mesh(new THREE.TorusGeometry(2.25, 0.07, 6, 48), new THREE.MeshBasicMaterial({ color: d.color }));
      rim.rotation.x = Math.PI / 2; rim.position.y = 0.24;
      const ring = new THREE.Mesh(new THREE.TorusGeometry(1.2, 0.035, 4, 32), new THREE.MeshBasicMaterial({ color: d.color, transparent: true, opacity: 0.5, blending: THREE.AdditiveBlending }));
      ring.rotation.x = Math.PI / 2; ring.position.y = 1.1;
      const glow = new THREE.Sprite(new THREE.SpriteMaterial({
        map: this.glowCyan, color: d.color, transparent: true, opacity: 0.5, blending: THREE.AdditiveBlending, depthWrite: false
      }));
      glow.position.y = 0.5; glow.scale.setScalar(4.2);
      g.add(base, top, rim, ring, glow);
      this.scene.add(g);
      this.jumpPads.push({
        position: V(d.x, 0.2, d.z), radius: 2.2, launch: d.launch,
        group: g, ring, top, glow, cooldown: 0, color: d.color
      });
      // danger marking around pad
      this.trim(d.x, 0.04, d.z, 6.4, 0.05, 0.12, new THREE.MeshBasicMaterial({ color: d.color, transparent: true, opacity: 0.3 }), { cast: false });
    }
  }

  buildSpawns() {
    const pts = [
      [0, 29], [0, -29], [29, 0], [-29, 0],
      [22, 22], [-22, 22], [22, -22], [-22, -22],
      [15, 0], [-15, 0], [0, 15], [0, -15],
    ];
    for (const [x, z] of pts) {
      if (Math.abs(x) < 9 && Math.abs(z) < 9) continue;
      const yaw = Math.atan2(-(0 - x), -(0 - z));
      this.spawnPoints.push({ pos: V(x, 0.06, z), yaw });
      // spawn marker decal
      this.trim(x, 0.04, z, 1.5, 0.04, 1.5, new THREE.MeshBasicMaterial({ color: 0x3fe9ff, transparent: true, opacity: 0.22 }), { cast: false });
    }
    // nav points
    for (let i = 0; i < 8; i++) {
      const a = (i / 8) * Math.PI * 2;
      this.navPoints.push(V(Math.cos(a) * 26, 0.1, Math.sin(a) * 26));
    }
    this.navPoints.push(V(0, 0.1, 10), V(0, 0.1, -10), V(10, 0.1, 0), V(-10, 0.1, 0));
    this.navPoints.push(V(25, 6.0, 0), V(-25, 6.0, 0), V(0, 4.6, 0));
  }

  buildDust() {
    const N = 240;
    const pos = new Float32Array(N * 3);
    const seeds = [];
    for (let i = 0; i < N; i++) {
      pos[i * 3] = (Math.random() - 0.5) * 90;
      pos[i * 3 + 1] = Math.random() * 30;
      pos[i * 3 + 2] = (Math.random() - 0.5) * 90;
      seeds.push(0.2 + Math.random() * 0.8);
    }
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    this.dust = new THREE.Points(g, new THREE.PointsMaterial({
      map: this.glowCyan, color: 0x7cdfff, size: 0.28, transparent: true, opacity: 0.5,
      blending: THREE.AdditiveBlending, depthWrite: false, sizeAttenuation: true
    }));
    this.dust.userData.seeds = seeds;
    this.scene.add(this.dust);
  }

  resetPickups() {
    for (const p of this.pickups) {
      p.active = true; p.timer = 0;
      p.group.visible = true;
    }
  }

  update(dt, time) {
    this.time = time;
    // pickups
    for (const p of this.pickups) {
      if (!p.active) {
        p.timer -= dt;
        if (p.timer <= 0) {
          p.active = true;
          p.group.visible = true;
          if (p.type === 'quad') { /* handled by game */ }
        }
        continue;
      }
      p.spin.rotation.y += dt * (p.type === 'quad' ? 0.9 : 1.6);
      p.spin.rotation.x = Math.sin(time * 0.7 + p.phase) * 0.18;
      p.spin.position.y = Math.sin(time * 1.5 + p.phase) * (p.bob + (p.type === 'quad' ? 0.14 : 0));
      p.ring.rotation.z += dt * 0.5;
      if (p.glow) p.glow.material.opacity = 0.55 + Math.sin(time * 2.4 + p.phase) * 0.18;
      if (p.light) p.light.intensity = (p.type === 'quad' ? 20 : 6) + Math.sin(time * 3 + p.phase) * 2;
    }
    // jump pads
    for (const pad of this.jumpPads) {
      pad.cooldown = Math.max(0, pad.cooldown - dt);
      pad.ring.rotation.z += dt * 1.7;
      pad.ring.position.y = 0.8 + Math.sin(time * 2 + pad.position.x) * 0.3;
      pad.top.material.opacity = 0.72 + Math.sin(time * 5 + pad.position.z) * 0.18;
      const s = 4.2 + Math.sin(time * 2.2 + pad.position.x) * 0.5;
      pad.glow.scale.setScalar(s);
    }
    // hologram
    if (this.holo) {
      this.holo.rotation.y = Math.sin(time * 0.18) * 0.55 + 0.2;
      this.holo.position.y = 9.6 + Math.sin(time * 0.8) * 0.15;
      this.holoMat.opacity = 0.55 + Math.sin(time * 7) * 0.08 + Math.sin(time * 1.6) * 0.1;
    }
    if (this.holoRing) {
      this.holoRing.rotation.x = 0.3 + Math.sin(time * 0.4) * 0.15;
      this.holoRing.rotation.z += dt * 0.3;
    }
    if (this.sign) this.sign.material.opacity = 0.7 + Math.sin(time * 2.2) * 0.12;
    // drones
    if (this.drones) for (const d of this.drones) {
      const a = d.userData.a + time * 0.08;
      d.position.x = Math.cos(a) * d.userData.r;
      d.position.z = Math.sin(a) * d.userData.r;
      d.position.y = d.userData.baseY + Math.sin(time * 0.9 + d.userData.i) * 1.2;
      d.lookAt(0, d.position.y, 0);
    }
    // dust
    if (this.dust) {
      const arr = this.dust.geometry.attributes.position.array;
      const seeds = this.dust.userData.seeds;
      for (let i = 0; i < seeds.length; i++) {
        arr[i * 3 + 1] += dt * (0.25 + seeds[i] * 0.4);
        if (arr[i * 3 + 1] > 32) arr[i * 3 + 1] = 0;
      }
      this.dust.geometry.attributes.position.needsUpdate = true;
    }
    // sky slowly rotates
    this.sky.rotation.y += dt * 0.0015;
    for (const r of this.decor) if (r.userData.spin) r.rotation.y += r.userData.spin * dt * 10;
  }

  // --------- physics helpers ----------
  overlaps(pos, radius, height) {
    const minY = pos.y, maxY = pos.y + height;
    for (const b of this.colliders) {
      if (pos.x + radius > b.min.x && pos.x - radius < b.max.x &&
          pos.z + radius > b.min.z && pos.z - radius < b.max.z &&
          maxY > b.min.y + 0.02 && minY < b.max.y - 0.02) return b;
    }
    return null;
  }

  groundHeight(x, z, y) {
    let top = -Infinity;
    for (const b of this.colliders) {
      if (x > b.min.x && x < b.max.x && z > b.min.z && z < b.max.z) {
        if (b.max.y <= y + 0.12 && b.max.y > top) top = b.max.y;
      }
    }
    return top;
  }

  collideSphere(point, radius) {
    for (const b of this.colliders) {
      const cx = Math.max(b.min.x, Math.min(point.x, b.max.x));
      const cy = Math.max(b.min.y, Math.min(point.y, b.max.y));
      const cz = Math.max(b.min.z, Math.min(point.z, b.max.z));
      const dx = point.x - cx, dy = point.y - cy, dz = point.z - cz;
      if (dx * dx + dy * dy + dz * dz < radius * radius) return true;
    }
    return false;
  }

  raycast(origin, dir, far = 200) {
    this.raycaster.set(origin, dir);
    this.raycaster.far = far;
    const hits = this.raycaster.intersectObjects(this.meshes, false);
    return hits.length ? hits[0] : null;
  }

  segmentBlocked(a, b) {
    const d = b.clone().sub(a);
    const len = d.length();
    if (len < 0.001) return false;
    const hit = this.raycast(a, d.normalize(), len - 0.1);
    return !!hit;
  }
}

// Shared capsule-ish movement for player and bots.
export function moveBody(body, world, dt, { stepHeight = 0.55, gravity = 26 } = {}) {
  const pos = body.position;
  const vel = body.velocity;
  const radius = body.radius;
  const height = body.height;
  let grounded = false;

  // horizontal, axis separated with step-up
  for (const axis of ['x', 'z']) {
    if (Math.abs(vel[axis]) < 0.0001) continue;
    const amount = vel[axis] * dt;
    const old = pos[axis];
    pos[axis] += amount;
    if (world.overlaps(pos, radius, height)) {
      // try step up
      const oldY = pos.y;
      pos.y += stepHeight;
      if (!world.overlaps(pos, radius, height)) {
        // keep lifted position, will settle on the step
      } else {
        pos.y = oldY;
        pos[axis] = old;
        // step out a hair to avoid sticking
        pos[axis] += Math.sign(amount) * 0.001;
        vel[axis] = 0;
      }
    }
  }

  // vertical
  vel.y -= gravity * dt;
  if (vel.y < -60) vel.y = -60;
  const oldY = pos.y;
  pos.y += vel.y * dt;
  const hit = world.overlaps(pos, radius, height);
  if (hit) {
    if (vel.y <= 0) {
      pos.y = hit.max.y;
      grounded = true;
      if (body.onLand && vel.y < -3) body.onLand(-vel.y);
    } else {
      pos.y = hit.min.y - height;
    }
    vel.y = 0;
  }
  // ground probe (standing still / step edges)
  if (!grounded && Math.abs(vel.y) < 0.5) {
    const top = world.groundHeight(pos.x, pos.z, pos.y + 0.12);
    if (top > -Infinity && pos.y - top < 0.12) {
      pos.y = top;
      grounded = true;
    }
  }

  // world bounds / kill floor
  body.grounded = grounded;
  if (pos.y < -24) body.fellOut = true;
  return grounded;
}

import * as THREE from 'three';
import { glowTexture } from './textures.js';

const MAX = 2600;

export class Effects {
  constructor(scene) {
    this.scene = scene;
    this.cursor = 0;
    this.parts = new Array(MAX);
    for (let i = 0; i < MAX; i++) this.parts[i] = { life: 0, max: 1 };
    const geo = new THREE.BufferGeometry();
    this.pos = new Float32Array(MAX * 3);
    this.col = new Float32Array(MAX * 3);
    this.size = new Float32Array(MAX);
    this.alpha = new Float32Array(MAX);
    geo.setAttribute('position', new THREE.BufferAttribute(this.pos, 3));
    geo.setAttribute('aColor', new THREE.BufferAttribute(this.col, 3));
    geo.setAttribute('aSize', new THREE.BufferAttribute(this.size, 1));
    geo.setAttribute('aAlpha', new THREE.BufferAttribute(this.alpha, 1));
    const mat = new THREE.ShaderMaterial({
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      uniforms: { uScale: { value: 1 } },
      vertexShader: `
        attribute vec3 aColor; attribute float aSize; attribute float aAlpha;
        varying vec3 vColor; varying float vAlpha;
        uniform float uScale;
        void main(){
          vColor = aColor; vAlpha = aAlpha;
          vec4 mv = modelViewMatrix * vec4(position,1.0);
          gl_PointSize = aSize * uScale * (220.0 / max(0.5, -mv.z));
          gl_Position = projectionMatrix * mv;
        }`,
      fragmentShader: `
        varying vec3 vColor; varying float vAlpha;
        void main(){
          vec2 c = gl_PointCoord - 0.5;
          float d = length(c);
          float a = smoothstep(0.5, 0.05, d) * vAlpha;
          if (a < 0.01) discard;
          gl_FragColor = vec4(vColor, a);
        }`
    });
    this.points = new THREE.Points(geo, mat);
    this.points.frustumCulled = false;
    this.points.renderOrder = 5;
    scene.add(this.points);
    this.geo = geo;
    this.uScale = mat.uniforms.uScale;

    // beam pool
    this.beams = [];
    const beamGeo = new THREE.BoxGeometry(1, 1, 1);
    for (let i = 0; i < 28; i++) {
      const m = new THREE.Mesh(beamGeo, new THREE.MeshBasicMaterial({
        color: 0xffffff, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false
      }));
      m.visible = false;
      m.frustumCulled = false;
      scene.add(m);
      this.beams.push({ mesh: m, life: 0, max: 1, width: 0.04 });
    }
    this.beamCursor = 0;

    // explosion spheres
    this.blasts = [];
    const sphereGeo = new THREE.IcosahedronGeometry(1, 2);
    for (let i = 0; i < 8; i++) {
      const m = new THREE.Mesh(sphereGeo, new THREE.MeshBasicMaterial({
        color: 0xffc070, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false
      }));
      m.visible = false;
      scene.add(m);
      this.blasts.push({ mesh: m, life: 0, max: 0.45, size: 1 });
    }
    this.blastCursor = 0;

    this.rings = [];
    const ringGeo = new THREE.RingGeometry(0.7, 1, 40);
    for (let i = 0; i < 6; i++) {
      const m = new THREE.Mesh(ringGeo, new THREE.MeshBasicMaterial({
        color: 0xffb060, transparent: true, opacity: 0, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false
      }));
      m.visible = false;
      scene.add(m);
      this.rings.push({ mesh: m, life: 0, max: 0.5, size: 1 });
    }
    this.ringCursor = 0;

    this.flash = new THREE.PointLight(0xffa040, 0, 22, 2);
    scene.add(this.flash);
    this.flashLife = 0;

    this.gibs = [];
    this.gibGeo = new THREE.BoxGeometry(1, 1, 1);
    this.time = 0;
  }

  setViewport(height, fov) {
    this.uScale.value = height / 900 * 1.15;
  }

  particle(p) {
    const i = this.cursor;
    this.cursor = (this.cursor + 1) % MAX;
    const s = this.parts[i];
    s.x = p.x; s.y = p.y; s.z = p.z;
    s.vx = p.vx || 0; s.vy = p.vy || 0; s.vz = p.vz || 0;
    s.r = p.r ?? 1; s.g = p.g ?? 1; s.b = p.b ?? 1;
    s.size = p.size ?? 0.2;
    s.life = s.max = p.life ?? 0.6;
    s.grav = p.grav ?? 0;
    s.drag = p.drag ?? 1.6;
    s.fade = p.fade ?? 1;
    s.growth = p.growth ?? 0;
  }

  burst(pos, count, { color = 0x3fe9ff, speed = 6, size = 0.22, life = 0.5, grav = 8, spread = 1, dir = null, drag = 2, growth = 0 } = {}) {
    const c = new THREE.Color(color);
    for (let i = 0; i < count; i++) {
      const v = new THREE.Vector3((Math.random() - 0.5) * 2, (Math.random() - 0.5) * 2, (Math.random() - 0.5) * 2);
      if (dir) v.lerp(dir, 0.35);
      v.normalize().multiplyScalar(speed * (0.3 + Math.random() * 0.8) * spread);
      const jitter = 0.8 + Math.random() * 0.5;
      this.particle({
        x: pos.x + (Math.random() - 0.5) * 0.15,
        y: pos.y + (Math.random() - 0.5) * 0.15,
        z: pos.z + (Math.random() - 0.5) * 0.15,
        vx: v.x, vy: v.y, vz: v.z,
        r: c.r * jitter, g: c.g * jitter, b: c.b * jitter,
        size: size * (0.7 + Math.random() * 0.7),
        life: life * (0.6 + Math.random() * 0.7),
        grav, drag, growth
      });
    }
  }

  spark(pos, normal, color = 0xffd27a, count = 7) {
    const n = normal || new THREE.Vector3(0, 1, 0);
    const c = new THREE.Color(color);
    for (let i = 0; i < count; i++) {
      const v = n.clone().multiplyScalar(0.6).add(new THREE.Vector3((Math.random() - 0.5) * 2, Math.random() * 1.6, (Math.random() - 0.5) * 2)).normalize().multiplyScalar(3 + Math.random() * 7);
      this.particle({
        x: pos.x, y: pos.y, z: pos.z, vx: v.x, vy: v.y, vz: v.z,
        r: c.r, g: c.g, b: c.b, size: 0.11 + Math.random() * 0.1,
        life: 0.18 + Math.random() * 0.3, grav: 16, drag: 0.8
      });
    }
  }

  beam(from, to, color = 0x66f6ff, width = 0.055, life = 0.14) {
    const b = this.beams[this.beamCursor];
    this.beamCursor = (this.beamCursor + 1) % this.beams.length;
    const dir = to.clone().sub(from);
    const len = dir.length();
    if (len < 0.01) return;
    const mesh = b.mesh;
    mesh.position.copy(from).add(to).multiplyScalar(0.5);
    mesh.lookAt(to);
    mesh.scale.set(width, width, len);
    mesh.material.color.set(color);
    mesh.material.opacity = 1;
    mesh.visible = true;
    b.life = b.max = life;
    b.width = width;
  }

  rail(from, to) {
    this.beam(from, to, 0x99fbff, 0.09, 0.28);
    this.beam(from, to, 0x3fe9ff, 0.2, 0.22);
    this.burst(from, 14, { color: 0x9dfbff, speed: 7, size: 0.18, life: 0.3, dir: to.clone().sub(from).normalize(), grav: 0 });
    const end = from.clone().lerp(to, 1);
    this.spark(end, to.clone().sub(from).normalize().negate(), 0x99fbff, 12);
  }

  explosion(pos, scale = 1) {
    const b = this.blasts[this.blastCursor];
    this.blastCursor = (this.blastCursor + 1) % this.blasts.length;
    b.mesh.position.copy(pos);
    b.mesh.material.color.set(0xffc46b);
    b.mesh.material.opacity = 1;
    b.mesh.visible = true;
    b.size = 2.2 * scale;
    b.life = b.max = 0.38;
    const r = this.rings[this.ringCursor];
    this.ringCursor = (this.ringCursor + 1) % this.rings.length;
    r.mesh.position.copy(pos);
    r.mesh.position.y = Math.max(0.1, pos.y - 0.2);
    r.mesh.rotation.x = -Math.PI / 2;
    r.mesh.material.opacity = 0.9;
    r.mesh.visible = true;
    r.size = 5 * scale;
    r.life = r.max = 0.5;

    this.burst(pos, 34, { color: 0xffb050, speed: 12 * scale, size: 0.34, life: 0.7, grav: 6, drag: 2.4 });
    this.burst(pos, 18, { color: 0xff5a2a, speed: 7 * scale, size: 0.5, life: 0.9, grav: 3, drag: 2 });
    this.burst(pos, 16, { color: 0xfff0c0, speed: 18 * scale, size: 0.13, life: 0.4, grav: 12, drag: 1 });
    this.flash.position.copy(pos);
    this.flash.color.set(0xffa050);
    this.flash.intensity = 90 * scale;
    this.flash.distance = 26;
    this.flashLife = 0.28;
  }

  gibs(pos, color = 0x8b95a8, dir = new THREE.Vector3(0, 1, 0)) {
    for (let i = 0; i < 11; i++) {
      const size = 0.12 + Math.random() * 0.26;
      const mat = new THREE.MeshStandardMaterial({
        color: Math.random() > 0.35 ? color : 0xff3b4e,
        roughness: 0.7, metalness: 0.2,
        transparent: true, opacity: 1
      });
      const m = new THREE.Mesh(this.gibGeo, mat);
      m.scale.set(size * (0.6 + Math.random()), size * (0.5 + Math.random() * 0.8), size * (0.6 + Math.random()));
      m.position.copy(pos).add(new THREE.Vector3((Math.random() - 0.5) * 0.5, Math.random() * 1.2, (Math.random() - 0.5) * 0.5));
      this.scene.add(m);
      this.gibs.push({
        mesh: m,
        v: new THREE.Vector3((Math.random() - 0.5) * 11, 5 + Math.random() * 8, (Math.random() - 0.5) * 11).addScaledVector(dir, 3),
        spin: new THREE.Vector3(Math.random() * 9, Math.random() * 9, Math.random() * 9),
        life: 2.4 + Math.random() * 1.4, max: 3.8
      });
    }
  }

  jet(pos, dir, color = 0x66eaff) {
    for (let i = 0; i < 2; i++) {
      const c = new THREE.Color(color);
      this.particle({
        x: pos.x + (Math.random() - 0.5) * 0.16,
        y: pos.y + Math.random() * 0.1,
        z: pos.z + (Math.random() - 0.5) * 0.16,
        vx: -dir.x * (2 + Math.random() * 3) + (Math.random() - 0.5) * 1.5,
        vy: -dir.y * (2 + Math.random() * 3) - 1 - Math.random() * 2,
        vz: -dir.z * (2 + Math.random() * 3) + (Math.random() - 0.5) * 1.5,
        r: c.r, g: c.g, b: c.b,
        size: 0.3 + Math.random() * 0.22,
        life: 0.16 + Math.random() * 0.2,
        grav: -2, drag: 2.5
      });
    }
  }

  update(dt, time) {
    this.time = time;
    for (let i = 0; i < MAX; i++) {
      const p = this.parts[i];
      if (p.life > 0) {
        p.life -= dt;
        if (p.life <= 0) {
          this.alpha[i] = 0;
          this.size[i] = 0;
          continue;
        }
        const d = Math.max(0, 1 - p.drag * dt);
        p.vx *= d; p.vy *= d; p.vz *= d;
        p.vy -= p.grav * dt;
        p.x += p.vx * dt; p.y += p.vy * dt; p.z += p.vz * dt;
        if (p.y < 0.05 && p.vy < 0) { p.y = 0.05; p.vy *= -0.3; p.vx *= 0.8; p.vz *= 0.8; }
        const k = p.life / p.max;
        this.pos[i * 3] = p.x; this.pos[i * 3 + 1] = p.y; this.pos[i * 3 + 2] = p.z;
        this.col[i * 3] = p.r; this.col[i * 3 + 1] = p.g; this.col[i * 3 + 2] = p.b;
        this.size[i] = p.size * (1 + p.growth * (1 - k));
        this.alpha[i] = Math.min(1, k * 1.8) * 0.9;
      } else {
        this.alpha[i] = 0;
      }
    }
    this.geo.attributes.position.needsUpdate = true;
    this.geo.attributes.aColor.needsUpdate = true;
    this.geo.attributes.aSize.needsUpdate = true;
    this.geo.attributes.aAlpha.needsUpdate = true;

    for (const b of this.beams) {
      if (b.life > 0) {
        b.life -= dt;
        const k = Math.max(0, b.life / b.max);
        b.mesh.material.opacity = k;
        b.mesh.scale.x = b.width * (0.4 + k * 0.8);
        b.mesh.scale.y = b.width * (0.4 + k * 0.8);
        if (b.life <= 0) b.mesh.visible = false;
      }
    }
    for (const b of this.blasts) {
      if (b.life > 0) {
        b.life -= dt;
        const k = Math.max(0, b.life / b.max);
        b.mesh.material.opacity = k * 0.9;
        const s = b.size * (1 + (1 - k) * 1.7);
        b.mesh.scale.setScalar(s);
        if (b.life <= 0) b.mesh.visible = false;
      }
    }
    for (const r of this.rings) {
      if (r.life > 0) {
        r.life -= dt;
        const k = Math.max(0, r.life / r.max);
        r.mesh.material.opacity = k * 0.7;
        r.mesh.scale.setScalar(r.size * (1 + (1 - k) * 2.2) * 0.4);
        if (r.life <= 0) r.mesh.visible = false;
      }
    }
    if (this.flashLife > 0) {
      this.flashLife -= dt;
      this.flash.intensity = Math.max(0, this.flash.intensity * (1 - dt * 12));
    } else if (this.flash.intensity !== 0) {
      this.flash.intensity = 0;
    }

    for (let i = this.gibs.length - 1; i >= 0; i--) {
      const g = this.gibs[i];
      g.life -= dt;
      g.v.y -= 26 * dt;
      g.mesh.position.addScaledVector(g.v, dt);
      g.mesh.rotation.x += g.spin.x * dt;
      g.mesh.rotation.y += g.spin.y * dt;
      g.mesh.rotation.z += g.spin.z * dt;
      if (g.mesh.position.y < 0.1) {
        g.mesh.position.y = 0.1;
        g.v.y = Math.abs(g.v.y) * 0.35;
        g.v.x *= 0.7; g.v.z *= 0.7;
        g.spin.multiplyScalar(0.7);
      }
      if (g.life < 0.8) g.mesh.material.opacity = Math.max(0, g.life / 0.8);
      if (g.life <= 0) {
        this.scene.remove(g.mesh);
        g.mesh.material.dispose();
        this.gibs.splice(i, 1);
      }
    }
  }

  clearGibs() {
    for (const g of this.gibs) { this.scene.remove(g.mesh); g.mesh.material.dispose(); }
    this.gibs.length = 0;
  }
}

