export class ViewModel {
  constructor(aspect) {
    this.scene = new THREE.Scene();
    this.camera = new THREE.PerspectiveCamera(74, aspect, 0.01, 10);
    this.camera.position.set(0, 0, 0);
    const hemi = new THREE.HemisphereLight(0xcfe8ff, 0x160a26, 2.2);
    this.scene.add(hemi);
    const key = new THREE.DirectionalLight(0xffd9e6, 3.2);
    key.position.set(-1.2, 2.2, 1.4);
    this.scene.add(key);
    const rim = new THREE.DirectionalLight(0x35d8ff, 2.0);
    rim.position.set(2.2, 0.4, -1.5);
    this.scene.add(rim);
    const warm = new THREE.PointLight(0xff7040, 12, 4);
    warm.position.set(0.4, -0.4, 0.4);
    this.scene.add(warm);

    this.root = new THREE.Group();
    this.scene.add(this.root);
    this.models = [buildScatter(), buildRocket(), buildRail(), buildSpin()];
    for (const m of this.models) {
      m.visible = false;
      m.scale.setScalar(1.0);
      this.root.add(m);
    }
    this.index = 0;
    this.models[0].visible = true;
    this.phase = 0;
    this.kick = 0;
    this.swap = 0;
    this.bobAmt = 0;
    this.basePos = new THREE.Vector3(0.32, -0.29, -0.62);
    this.root.position.copy(this.basePos);
    this.swing = { x: 0, y: 0 };

    const flashTex = glowTexture('rgba(255,250,220,1)', 'rgba(255,170,60,.7)', 'rgba(255,80,0,0)');
    this.flash = new THREE.Sprite(new THREE.SpriteMaterial({
      map: flashTex, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false, depthTest: false
    }));
    this.flash.scale.setScalar(0.5);
    this.scene.add(this.flash);
    this.flashLife = 0;

    this.discSpin = 0;
  }

  setAspect(aspect) {
    this.camera.aspect = aspect;
    this.camera.updateProjectionMatrix();
  }

  show(index, instant = false) {
    if (index === this.index && !instant) return;
    this.models[this.index].visible = false;
    this.index = index;
    this.models[index].visible = true;
    if (!instant) this.swap = 1;
  }

  fire() {
    this.kick = 1;
    this.flashLife = 0.075;
    const m = this.models[this.index];
    const muzzle = m.userData.muzzle;
    // flash position in view scene: root offset + local muzzle
    this.flash.position.copy(this.root.position).add(muzzle);
    this.flash.position.x += 0.02;
    this.flash.position.y += 0.03;
    const s = 0.35 + Math.random() * 0.25;
    this.flash.scale.setScalar(s * (this.index === 0 ? 1.2 : 1.6));
    this.flash.material.rotation = Math.random() * 6.28;
    this.flash.material.opacity = 1;
  }

  update(dt, { moving = 0, grounded = true, speed = 0, lookX = 0, lookY = 0, time = 0, spread = 0 } = {}) {
    this.phase += dt * (grounded ? Math.max(1.2, speed * 1.15) : 2.2);
    const moveAmt = Math.min(1, speed / 9) * (grounded ? 1 : 0.35);
    this.bobAmt += (moveAmt - this.bobAmt) * Math.min(1, dt * 8);
    const bobX = Math.sin(this.phase) * 0.016 * this.bobAmt;
    const bobY = Math.abs(Math.cos(this.phase)) * 0.014 * this.bobAmt;

    // sway from look delta (clamped)
    this.swing.x += ((THREE.MathUtils.clamp(-lookX * 0.0009, -0.05, 0.05)) - this.swing.x) * Math.min(1, dt * 9);
    this.swing.y += ((THREE.MathUtils.clamp(lookY * 0.0007, -0.04, 0.04)) - this.swing.y) * Math.min(1, dt * 9);

    this.kick = Math.max(0, this.kick - dt * 8);
    this.swap = Math.max(0, this.swap - dt * 6);
    const kick = this.kick * this.kick;
    const swapDown = this.swap * 0.22;

    this.root.position.set(
      this.basePos.x + bobX + this.swing.x,
      this.basePos.y + bobY + this.swing.y - swapDown - kick * 0.02,
      this.basePos.z + kick * (this.models[this.index].userData.kick || 0.1) + swapDown * 0.5
    );
    this.root.rotation.set(
      -this.swing.y * 0.6 + kick * 0.06 + swapDown * 0.4,
      this.swing.x * 1.1,
      -this.swing.x * 0.3 + kick * 0.02
    );
    // muzzle flash
    if (this.flashLife > 0) {
      this.flashLife -= dt;
      this.flash.material.opacity = Math.max(0, this.flashLife / 0.075);
    } else {
      this.flash.material.opacity = 0;
    }
    // spin disc
    const m = this.models[this.index];
    if (m.userData.spinDisc) {
      this.discSpin += dt * 8;
      m.userData.spinDisc.rotation.z = this.discSpin;
    }
    // subtle idle breathing
    this.root.position.y += Math.sin(time * 1.4) * 0.002;
  }
}

import * as THREE from 'three';
import { moveBody } from './world.js';
import { WEAPONS } from './weapons.js';

const UP = new THREE.Vector3(0, 1, 0);

export class Player {
  constructor() {
    this.name = 'YOU';
    this.isPlayer = true;
    this.color = 0x3fe9ff;
    this.radius = 0.4;
    this.height = 1.8;
    this.eye = 1.62;
    this.position = new THREE.Vector3(0, 0.05, 28);
    this.velocity = new THREE.Vector3();
    this.yaw = 0;
    this.pitch = 0;
    this.health = 100;
    this.armor = 50;
    this.maxHealth = 100;
    this.maxArmor = 100;
    this.alive = true;
    this.grounded = false;
    this.fuel = 100;
    this.maxFuel = 100;
    this.skiing = false;
    this.jetting = false;
    this.score = 0;
    this.deaths = 0;
    this.streak = 0;
    this.bestStreak = 0;
    this.protection = 0;
    this.quad = 0;
    this.weaponIndex = 0;
    this.lastWeapon = 1;
    this.ammo = { scatter: Infinity, rocket: 8, rail: 6, spin: 8 };
    this.fireTimer = 0;
    this.switchTimer = 0;
    this.landDip = 0;
    this.bob = 0;
    this.stepTimer = 0;
    this.fellOut = false;
    this.damageFlash = 0;
    this.hitFlash = 0;
    this.respawnTimer = 0;
    this.killerName = '';
    this.deathCause = '';
    this.padCooldown = 0;
    this.lastLook = { x: 0, y: 0 };
    this.onGroundImpact = null;
  }

  reset() {
    this.alive = true;
    this.health = this.maxHealth;
    this.armor = 50;
    this.fuel = this.maxFuel;
    this.velocity.set(0, 0, 0);
    this.score = 0;
    this.deaths = 0;
    this.streak = 0;
    this.bestStreak = 0;
    this.quad = 0;
    this.protection = 0;
    this.weaponIndex = 0;
    this.lastWeapon = 1;
    this.ammo = { scatter: Infinity, rocket: 8, rail: 6, spin: 8 };
    this.fireTimer = 0;
    this.switchTimer = 0;
    this.fellOut = false;
    this.respawnTimer = 0;
  }

  spawn(world, spawn) {
    const s = spawn || world.spawnPoints[Math.floor(Math.random() * world.spawnPoints.length)];
    this.position.copy(s.pos);
    this.velocity.set(0, 0, 0);
    this.yaw = s.yaw;
    this.pitch = 0;
    this.alive = true;
    this.health = 100;
    this.armor = 50;
    this.fuel = 100;
    this.protection = 1.6;
    this.quad = 0;
    this.streak = 0;
    this.fellOut = false;
    this.fireTimer = 0;
    this.weaponIndex = 0;
    this.ammo.rocket = Math.max(this.ammo.rocket, 8);
    this.ammo.rail = Math.max(this.ammo.rail, 4);
    this.ammo.spin = Math.max(this.ammo.spin, 6);
    this.landDip = 0;
  }

  get eyePosition() {
    return new THREE.Vector3(this.position.x, this.position.y + this.eye - this.landDip, this.position.z);
  }

  get forward() {
    return new THREE.Vector3(-Math.sin(this.yaw) * Math.cos(this.pitch), Math.sin(this.pitch), -Math.cos(this.yaw) * Math.cos(this.pitch));
  }

  get flatForward() {
    return new THREE.Vector3(-Math.sin(this.yaw), 0, -Math.cos(this.yaw));
  }

  get flatRight() {
    return new THREE.Vector3(Math.cos(this.yaw), 0, -Math.sin(this.yaw));
  }

  update(dt, input, world, game, camera) {
    if (!this.alive) return;
    this.protection = Math.max(0, this.protection - dt);
    this.quad = Math.max(0, this.quad - dt);
    this.landDip = Math.max(0, this.landDip - dt * 5);
    this.damageFlash = Math.max(0, this.damageFlash - dt * 2.5);
    this.hitFlash = Math.max(0, this.hitFlash - dt * 4);
    this.padCooldown = Math.max(0, this.padCooldown - dt);
    this.switchTimer = Math.max(0, this.switchTimer - dt);
    this.fireTimer = Math.max(0, this.fireTimer - dt);

    // look
    const look = input.consumeLook();
    const sens = 0.0022 * (game.sensitivity || 1);
    this.yaw -= look.x * sens;
    this.pitch -= look.y * sens;
    this.pitch = THREE.MathUtils.clamp(this.pitch, -1.45, 1.45);
    this.lastLook.x = look.x;
    this.lastLook.y = look.y;

    // weapon selection
    for (let i = 0; i < WEAPONS.length; i++) {
      if (input.wasPressed(`Digit${i + 1}`) || input.wasPressed(`Numpad${i + 1}`)) this.selectWeapon(i, game);
    }
    const wheel = input.consumeWheel();
    if (wheel !== 0) this.selectWeapon((this.weaponIndex + (wheel > 0 ? 1 : WEAPONS.length - 1)) % WEAPONS.length, game);
    if (input.wasPressed('KeyQ')) this.selectWeapon(this.lastWeapon, game);
    if (input.wasPressed('KeyR')) this.selectWeapon(0, game);

    // movement
    const move = input.move;
    const ski = input.isDown('ShiftLeft') || input.isDown('ShiftRight') || input.touch.jet && false;
    this.skiing = ski && this.grounded && this.velocity.lengthSq() > 1.5;

    const wish = this.flatForward.multiplyScalar(move.z).add(this.flatRight.multiplyScalar(move.x));
    const wishLen = wish.length();
    if (wishLen > 1) wish.divideScalar(wishLen);
    const wishSpeed = ski && this.grounded ? 13.4 : 9.6;
    const maxSpeed = ski ? 20 : 15;

    if (this.grounded) {
      // friction
      const hs = Math.hypot(this.velocity.x, this.velocity.z);
      if (hs > 0.01) {
        const friction = ski ? 0.6 : 7.2;
        const drop = Math.max(hs * friction * dt, friction * dt * 0.6);
        const k = Math.max(0, hs - drop) / hs;
        this.velocity.x *= k;
        this.velocity.z *= k;
      }
      this.accelerate(wish, wishSpeed, 68, dt, maxSpeed);
    } else {
      this.accelerate(wish, Math.min(wishSpeed * 1.05, 10.2), 42, dt, 23);
    }

    // jump + jetpack
    const jetHeld = input.jetHeld;
    if (input.wasPressed('Space') && this.grounded) {
      this.velocity.y = 10.6;
      this.grounded = false;
      this.fuel = Math.max(0, this.fuel - 3);
      game.audio.jump();
      game.effects.burst(this.position.clone().setY(this.position.y + 0.1), 6, {
        color: 0x7ddcff, speed: 3.2, size: 0.18, life: 0.3, grav: 4
      });
    }
    this.jetting = false;
    if (jetHeld && !this.grounded && this.fuel > 0.5) {
      this.velocity.y += 44 * dt;
      if (this.velocity.y > 9.0) this.velocity.y = 9.0;
      this.fuel = Math.max(0, this.fuel - 24 * dt);
      this.jetting = true;
      // flame from feet
      if (Math.random() < 0.9) {
        const down = new THREE.Vector3((Math.random() - 0.5) * 0.4, -1, (Math.random() - 0.5) * 0.4).normalize();
        const p = this.position.clone().add(new THREE.Vector3((Math.random() - 0.5) * 0.4, 1.0, (Math.random() - 0.5) * 0.4));
        game.effects.jet(p, down, Math.random() > 0.5 ? 0x66eaff : 0xffa040);
      }
    }
    if (this.grounded && !this.jetting) {
      this.fuel = Math.min(this.maxFuel, this.fuel + 26 * dt);
    }
    game.audio.setJet(this.jetting, this.fuel / this.maxFuel);

    // integrate with collisions
    const wasGrounded = this.grounded;
    const velYBefore = this.velocity.y;
    this.fellOut = false;
    moveBody(this, world, dt, { stepHeight: 0.7, gravity: 26 });
    if (!wasGrounded && this.grounded && velYBefore < -5) {
      this.landDip = Math.min(0.28, Math.abs(velYBefore) * 0.018);
      game.audio.land();
      game.effects.burst(this.position.clone().setY(this.position.y + 0.08), 8, {
        color: 0x93a9bb, speed: 2.4, size: 0.16, life: 0.35, grav: 5
      });
    }
    if (this.grounded) this.grounded = true;
    this.position.y = Math.max(this.position.y, -30);

    // jump pads
    for (const pad of world.jumpPads) {
      const dx = this.position.x - pad.position.x;
      const dz = this.position.z - pad.position.z;
      if (this.padCooldown <= 0 && Math.abs(this.position.y - pad.position.y) < 1.2 && dx * dx + dz * dz < pad.radius * pad.radius) {
        this.velocity.copy(pad.launch);
        this.padCooldown = 1.3;
        this.grounded = false;
        this.fuel = Math.min(this.maxFuel, this.fuel + 18);
        game.audio.pad();
        game.effects.burst(this.position.clone(), 24, { color: pad.color, speed: 9, size: 0.3, life: 0.6, grav: 2 });
        game.hud.toast('JUMP PAD — AIRBORNE');
      }
    }

    // pickups
    for (const p of world.pickups) {
      if (!p.active) continue;
      const dx = p.position.x - this.position.x;
      const dz = p.position.z - this.position.z;
      const dy = p.position.y - (this.position.y + 1.0);
      if (dx * dx + dz * dz < 2.2 * 2.2 && Math.abs(dy) < 2.1) {
        game.collectPickup(p, this);
      }
    }

    if (this.fellOut) this.fellOut = false;

    // footsteps
    const hspeed = Math.hypot(this.velocity.x, this.velocity.z);
    if (this.grounded && hspeed > 3.5) {
      this.stepTimer -= dt * hspeed;
      if (this.stepTimer <= 0) {
        this.stepTimer = 4.2;
        game.audio.noise({ dur: 0.055, vol: 0.05, freq: 640, to: 220, type: 'bandpass' });
      }
    }

    // weapons
    if (input.firing && this.fireTimer <= 0 && this.switchTimer <= 0) {
      const w = WEAPONS[this.weaponIndex];
      if (this.ammo[w.id] > 0 || w.infinite) {
        game.firePlayerWeapon(this, w);
        this.fireTimer = w.rate;
      } else {
        // dry click + auto switch to scatter
        if (this.fireTimer <= 0) {
          game.audio.tone({ f: 260, to: 180, dur: 0.05, type: 'square', vol: 0.05 });
          this.selectWeapon(0, game);
          this.fireTimer = 0.25;
        }
      }
    }

    // camera
    const hspeedNorm = Math.min(1, hspeed / 10);
    this.bob += dt * (this.grounded ? hspeed * 1.1 : 0.6);
    const bobY = Math.sin(this.bob * 2) * 0.026 * hspeedNorm * (this.grounded ? 1 : 0.3);
    const bobX = Math.cos(this.bob) * 0.018 * hspeedNorm;
    const strafe = move.x;
    const roll = -strafe * 0.022 + Math.sin(this.bob) * 0.003 * hspeedNorm;

    camera.position.set(this.position.x + bobX * 0.4, this.position.y + this.eye + bobY - this.landDip, this.position.z);
    camera.rotation.order = 'YXZ';
    camera.rotation.y = this.yaw;
    camera.rotation.x = this.pitch;
    camera.rotation.z = roll;
    this.viewBob = { bobY, bobX, hspeed, strafe };
  }

  accelerate(wish, wishSpeed, accel, dt, maxSpeed) {
    if (wish.lengthSq() < 0.0001) return;
    const hs = Math.hypot(this.velocity.x, this.velocity.z);
    if (hs >= maxSpeed) return;
    const add = Math.min(accel * dt, wishSpeed);
    this.velocity.x += wish.x * add;
    this.velocity.z += wish.z * add;
    // soft cap
    if (hs > maxSpeed) {
      const k = maxSpeed / hs;
      this.velocity.x *= k;
      this.velocity.z *= k;
    }
  }

  selectWeapon(i, game) {
    i = ((i % WEAPONS.length) + WEAPONS.length) % WEAPONS.length;
    if (i === this.weaponIndex) return;
    const w = WEAPONS[i];
    if (!w.infinite && this.ammo[w.id] <= 0) {
      game.hud.toast('OUT OF AMMO — FIND A CRATE');
      return;
    }
    this.lastWeapon = this.weaponIndex;
    this.weaponIndex = i;
    this.switchTimer = 0.18;
    game.audio.ui();
    game.viewModel.show(i);
    game.hud.flashWeapon();
  }

  takeDamage(amount, source, game, cause = 'fragged') {
    if (!this.alive || this.protection > 0) return;
    let dmg = amount;
    if (this.quad > 0) dmg *= 0.82;
    const armorAbsorb = Math.min(this.armor, dmg * 0.64);
    this.armor -= armorAbsorb;
    const hpDmg = dmg - armorAbsorb;
    this.health -= hpDmg;
    this.damageFlash = 1;
    game.audio.hurt();
    game.hud.damage(source ? source.position : null, this);
    if (this.health <= 0) {
      this.health = 0;
      game.kill(this, source, cause);
    }
  }

  addHealth(n) {
    this.health = Math.min(140, this.health + n);
  }
  addArmor(n) {
    this.armor = Math.min(150, this.armor + n);
  }
}

import * as THREE from 'three';
import { moveBody } from './world.js';
import { nameTexture } from './textures.js';

const BOT_DEFS = [
  { name: 'RANGER', color: 0x3fe9ff, trim: 0x0a7f9a, skill: 0.9, aggro: 0.8, rate: 1.18, spread: 0.035 },
  { name: 'VISOR', color: 0xff2e8a, trim: 0x8c1146, skill: 0.82, aggro: 1.0, rate: 1.32, spread: 0.045 },
  { name: 'KLESK', color: 0xffb02e, trim: 0x995c0a, skill: 0.76, aggro: 0.7, rate: 1.42, spread: 0.06 },
  { name: 'SARGE', color: 0x51ffb0, trim: 0x117a52, skill: 0.86, aggro: 0.9, rate: 1.26, spread: 0.04 },
];

let idCounter = 0;

function mat(color, metal = 0.75, rough = 0.4, emissive = 0x000000, ei = 0) {
  return new THREE.MeshStandardMaterial({ color, metalness: metal, roughness: rough, emissive, emissiveIntensity: ei });
}

export class Bot {
  constructor(def, index) {
    this.id = ++idCounter;
    this.name = def.name;
    this.color = def.color;
    this.trim = def.trim;
    this.skill = def.skill;
    this.aggro = def.aggro;
    this.rate = def.rate;
    this.spread = def.spread;
    this.index = index;
    this.isPlayer = false;
    this.radius = 0.48;
    this.height = 2.0;
    this.eye = 1.7;
    this.position = new THREE.Vector3();
    this.velocity = new THREE.Vector3();
    this.yaw = Math.PI;
    this.health = 100;
    this.armor = 0;
    this.alive = false;
    this.grounded = false;
    this.fuel = 100;
    this.jetting = false;
    this.score = 0;
    this.deaths = 0;
    this.streak = 0;
    this.bestStreak = 0;
    this.protection = 0;
    this.quad = 0;
    this.fireTimer = 1 + Math.random();
    this.thinkTimer = Math.random() * 0.3;
    this.strafeTimer = 0;
    this.strafeDir = Math.random() > 0.5 ? 1 : -1;
    this.jetTimer = 0;
    this.jumpTimer = 0;
    this.target = null;
    this.lastKnown = new THREE.Vector3();
    this.wander = new THREE.Vector3();
    this.wanderTimer = 0;
    this.stuckTimer = 0;
    this.stuck = false;
    this.flash = 0;
    this.respawnTimer = 0;
    this.killerName = '';
    this.trailTimer = 0;
    this.aimError = new THREE.Vector3();
    this.aimTimer = 0;
    this.buildModel();
  }

  buildModel() {
    const col = this.color;
    const dark = mat(0x1a2030, 0.8, 0.45);
    const armor = mat(0x2a3247, 0.72, 0.42);
    const accent = mat(this.trim, 0.6, 0.4, this.trim, 0.35);
    const skin = mat(0x8d7b6a, 0.1, 0.85);
    const glow = new THREE.MeshBasicMaterial({ color: col });
    const glowSoft = new THREE.MeshBasicMaterial({ color: col, transparent: true, opacity: 0.6, blending: THREE.AdditiveBlending, depthWrite: false });
    this.mats = [dark, armor, accent, skin];

    const g = new THREE.Group();
    this.model = g;
    const body = new THREE.Group();
    g.add(body);
    this.bodyGroup = body;

    // legs
    this.legs = [];
    for (const s of [-1, 1]) {
      const leg = new THREE.Group();
      leg.position.set(s * 0.19, 0.94, 0);
      const thigh = new THREE.Mesh(new THREE.BoxGeometry(0.24, 0.52, 0.26), armor);
      thigh.position.y = -0.22; thigh.castShadow = true;
      const shin = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.48, 0.22), dark);
      shin.position.y = -0.68; shin.castShadow = true;
      const boot = new THREE.Mesh(new THREE.BoxGeometry(0.25, 0.16, 0.38), accent);
      boot.position.set(0, -0.94, 0.05); boot.castShadow = true;
      const knee = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.12, 0.24), glow);
      knee.position.set(0, -0.48, 0.02);
      leg.add(thigh, shin, boot, knee);
      body.add(leg);
      this.legs.push(leg);
    }

    // torso
    const torso = new THREE.Mesh(new THREE.BoxGeometry(0.66, 0.72, 0.4), armor);
    torso.position.y = 1.34; torso.castShadow = true;
    body.add(torso);
    const chest = new THREE.Mesh(new THREE.BoxGeometry(0.52, 0.34, 0.1), accent);
    chest.position.set(0, 1.42, 0.24);
    body.add(chest);
    const belt = new THREE.Mesh(new THREE.BoxGeometry(0.56, 0.14, 0.34), dark);
    belt.position.y = 0.98;
    body.add(belt);
    const core = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.12, 0.06), glow);
    core.position.set(0, 1.48, 0.3);
    body.add(core);

    // head
    const neck = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.12, 0.2), dark);
    neck.position.y = 1.74;
    body.add(neck);
    const head = new THREE.Mesh(new THREE.BoxGeometry(0.36, 0.34, 0.36), armor);
    head.position.y = 1.98; head.castShadow = true;
    body.add(head);
    const visor = new THREE.Mesh(new THREE.BoxGeometry(0.32, 0.12, 0.06), glow);
    visor.position.set(0, 2.0, 0.19);
    body.add(visor);
    const crest = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.14, 0.3), accent);
    crest.position.set(0, 2.18, -0.02);
    body.add(crest);
    const antenna = new THREE.Mesh(new THREE.CylinderGeometry(0.012, 0.012, 0.36, 5), glow);
    antenna.position.set(-0.14, 2.3, -0.1); antenna.rotation.z = 0.2;
    body.add(antenna);

    // shoulders + arms
    this.arms = [];
    for (const s of [-1, 1]) {
      const shoulder = new THREE.Mesh(new THREE.BoxGeometry(0.26, 0.24, 0.34), accent);
      shoulder.position.set(s * 0.46, 1.58, 0);
      shoulder.castShadow = true;
      body.add(shoulder);
      const arm = new THREE.Group();
      arm.position.set(s * 0.46, 1.5, 0);
      const upper = new THREE.Mesh(new THREE.BoxGeometry(0.17, 0.42, 0.18), dark);
      upper.position.y = -0.24; upper.castShadow = true;
      const fore = new THREE.Mesh(new THREE.BoxGeometry(0.15, 0.36, 0.16), armor);
      fore.position.set(0, -0.58, 0.03);
      const hand = new THREE.Mesh(new THREE.BoxGeometry(0.13, 0.12, 0.14), glow);
      hand.position.set(0, -0.78, 0.05);
      arm.add(upper, fore, hand);
      body.add(arm);
      this.arms.push(arm);
    }

    // jetpack
    const pack = new THREE.Mesh(new THREE.BoxGeometry(0.46, 0.56, 0.24), dark);
    pack.position.set(0, 1.38, -0.3); pack.castShadow = true;
    body.add(pack);
    this.nozzles = [];
    for (const s of [-1, 1]) {
      const tank = new THREE.Mesh(new THREE.CylinderGeometry(0.09, 0.11, 0.5, 8), armor);
      tank.position.set(s * 0.18, 1.38, -0.42);
      body.add(tank);
      const noz = new THREE.Mesh(new THREE.ConeGeometry(0.11, 0.2, 8), dark);
      noz.position.set(s * 0.18, 1.06, -0.42);
      noz.rotation.x = Math.PI;
      body.add(noz);
      this.nozzles.push(noz);
      const flame = new THREE.Sprite(new THREE.SpriteMaterial({
        map: null, color: col, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false
      }));
      flame.position.set(s * 0.18, 0.96, -0.42);
      flame.scale.setScalar(0.5);
      body.add(flame);
      this[`flame${s > 0 ? 'R' : 'L'}`] = flame;
    }

    // weapon (held to the right)
    const weapon = new THREE.Group();
    weapon.position.set(0.38, 1.28, 0.2);
    weapon.rotation.set(0.05, 0, 0);
    const gunBody = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.14, 0.62), dark);
    gunBody.position.z = 0.16;
    const barrel = new THREE.Mesh(new THREE.CylinderGeometry(0.045, 0.055, 0.44, 8), armor);
    barrel.rotation.x = Math.PI / 2;
    barrel.position.z = 0.58;
    const coil = new THREE.Mesh(new THREE.TorusGeometry(0.075, 0.02, 5, 12), glow);
    coil.position.z = 0.45;
    const disc = new THREE.Mesh(new THREE.CylinderGeometry(0.13, 0.13, 0.03, 16), glowSoft);
    disc.rotation.x = Math.PI / 2;
    disc.position.z = 0.62;
    weapon.add(gunBody, barrel, coil, disc);
    body.add(weapon);
    this.weaponModel = weapon;
    this.weaponGlow = disc;

    // name tag
    const tex = nameTexture(this.name, '#' + this.color.toString(16).padStart(6, '0'));
    this.tag = new THREE.Sprite(new THREE.SpriteMaterial({
      map: tex, transparent: true, opacity: 0.9, depthWrite: false, depthTest: false
    }));
    this.tag.position.y = 2.72;
    this.tag.scale.set(2.3, 0.575, 1);
    g.add(this.tag);

    // team light aura
    const aura = new THREE.Sprite(new THREE.SpriteMaterial({
      map: null, color: col, transparent: true, opacity: 0.28, blending: THREE.AdditiveBlending, depthWrite: false
    }));
    aura.position.y = 1.2;
    aura.scale.setScalar(2.4);
    g.add(aura);
    this.aura = aura;

    // hit sphere marker (invisible-ish white flash sphere)
    const flash = new THREE.Mesh(new THREE.SphereGeometry(1.0, 12, 8), new THREE.MeshBasicMaterial({
      color: 0xffffff, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false
    }));
    flash.position.y = 1.2;
    flash.scale.set(0.7, 1.2, 0.7);
    g.add(flash);
    this.flashMesh = flash;

    g.traverse((o) => { if (o.isMesh) o.castShadow = true; });
    g.visible = false;
    this.scene = null;
  }

  addTo(scene) {
    if (!this.scene) { this.scene = scene; scene.add(this.model); }
  }

  spawn(world, spawn) {
    const s = spawn || world.spawnPoints[Math.floor(Math.random() * world.spawnPoints.length)];
    this.position.copy(s.pos);
    this.position.x += (Math.random() - 0.5) * 1.2;
    this.position.z += (Math.random() - 0.5) * 1.2;
    this.velocity.set(0, 0, 0);
    this.health = 100;
    this.armor = 0;
    this.alive = true;
    this.fuel = 100;
    this.protection = 1.5;
    this.target = null;
    this.fireTimer = 0.8 + Math.random() * 0.8;
    this.thinkTimer = 0.1;
    this.wanderTimer = 0;
    this.jetTimer = 0;
    this.streak = 0;
    this.killerName = '';
    this.model.visible = true;
    this.model.position.copy(this.position);
    this.yaw = s.yaw;
    this.model.rotation.y = this.yaw;
  }

  get eyePosition() {
    return new THREE.Vector3(this.position.x, this.position.y + this.eye, this.position.z);
  }

  get center() {
    return new THREE.Vector3(this.position.x, this.position.y + 1.0, this.position.z);
  }

  hurt(amount, source, game, cause = 'fragged') {
    if (!this.alive || this.protection > 0) return;
    this.health -= amount;
    this.flash = 1;
    this.flashMesh.material.opacity = 0.35;
    game.audio.hit();
    if (this.health <= 0) {
      this.health = 0;
      game.kill(this, source, cause);
    } else if (source && source.isPlayer) {
      game.hud.hitmarker(false);
    }
  }

  update(dt, game) {
    if (!this.alive) return;
    const world = game.world;
    this.protection = Math.max(0, this.protection - dt);
    this.fireTimer -= dt;
    this.thinkTimer -= dt;
    this.strafeTimer -= dt;
    this.wanderTimer -= dt;
    this.jetTimer = Math.max(0, this.jetTimer - dt);
    this.jumpTimer -= dt;
    this.flash = Math.max(0, this.flash - dt * 5);
    this.flashMesh.material.opacity = this.flash * 0.3;
    this.aimTimer -= dt;

    // ---------- targeting ----------
    if (this.thinkTimer <= 0) {
      this.thinkTimer = 0.35 + Math.random() * 0.3;
      const candidates = game.combatants.filter(e => e !== this && e.alive);
      let best = null, bestScore = -Infinity;
      const eye = this.eyePosition;
      for (const c of candidates) {
        const d = c.position.distanceTo(this.position);
        if (d > 62) continue;
        let score = 30 - d * 0.3;
        if (c.isPlayer) score += 7; // player draws attention, keeps action centered
        const visible = !world.segmentBlocked(eye, c.eyePosition);
        if (visible) score += 26;
        if (c === this.target) score += 8;
        if (c.health < 40) score += 5;
        if (score > bestScore) { bestScore = score; best = c; }
      }
      this.target = best;
      if (best && (!world.segmentBlocked(this.eyePosition, best.eyePosition))) {
        this.lastKnown.copy(best.position);
      }
    }

    const t = this.target;
    const tDist = t ? this.position.distanceTo(t.position) : 0;
    const canSee = t && t.alive && !world.segmentBlocked(this.eyePosition, t.eyePosition) && tDist < 62;

    // ---------- choose movement intention ----------
    let wishX = 0, wishZ = 0;
    let wishSpeed = 8.4;
    let wantJet = false;
    let wantJump = false;

    if (t && t.alive) {
      const dx = t.position.x - this.position.x;
      const dz = t.position.z - this.position.z;
      const dist = Math.hypot(dx, dz) || 0.001;
      const nx = dx / dist, nz = dz / dist;
      const ideal = 13 + (1 - this.skill) * 8;
      let forwardAmt = 0;
      if (dist > ideal + 5) forwardAmt = 1;
      else if (dist < ideal - 4) forwardAmt = -0.9;
      else forwardAmt = 0.05;

      if (this.strafeTimer <= 0) {
        this.strafeTimer = 0.7 + Math.random() * 1.1;
        this.strafeDir *= -1;
        if (Math.random() < 0.35) this.strafeDir = 0;
      }
      const strafe = canSee ? this.strafeDir * 0.85 : 0;
      wishX = nx * forwardAmt - nz * strafe;
      wishZ = nz * forwardAmt + nx * strafe;

      // elevation / jet use
      const dy = t.position.y - this.position.y;
      if ((dy > 2.2 && dist > 6) || (this.stuck && canSee)) wantJet = true;
      if (canSee && Math.random() < dt * (0.22 + this.aggro * 0.3)) wantJet = true;
      // retreat with jets when badly hurt
      if (this.health < 32 && Math.random() < dt * 0.5) wantJet = true;
      // hop while strafing
      if (this.grounded && Math.random() < dt * 0.5) wantJump = true;
      if (this.grounded && dist > 23 && Math.random() < dt * 0.7) wantJet = true;
    } else {
      // wander
      if (this.wanderTimer <= 0 || this.position.distanceTo(this.wander) < 2.5) {
        const pts = world.navPoints;
        this.wander.copy(pts[Math.floor(Math.random() * pts.length)]);
        this.wanderTimer = 5 + Math.random() * 4;
      }
      const dx = this.wander.x - this.position.x;
      const dz = this.wander.z - this.position.z;
      const d = Math.hypot(dx, dz) || 1;
      wishX = dx / d; wishZ = dz / d;
      if (this.wander.y > this.position.y + 1.5) wantJet = true;
      if (this.grounded && Math.random() < dt * 0.2) wantJet = true;
    }

    // separation from other bots
    for (const b of game.bots) {
      if (b === this || !b.alive) continue;
      const dx = this.position.x - b.position.x;
      const dz = this.position.z - b.position.z;
      const d2 = dx * dx + dz * dz;
      if (d2 < 9 && d2 > 0.001) {
        const d = Math.sqrt(d2);
        wishX += (dx / d) * (1.4 - d * 0.12);
        wishZ += (dz / d) * (1.4 - d * 0.12);
      }
    }

    const wl = Math.hypot(wishX, wishZ);
    if (wl > 1) { wishX /= wl; wishZ /= wl; }
    const accel = this.grounded ? 34 : 24;
    this.velocity.x += wishX * accel * dt;
    this.velocity.z += wishZ * accel * dt;
    const hs = Math.hypot(this.velocity.x, this.velocity.z);
    const cap = 8.8;
    if (hs > cap) {
      const k = Math.max(cap, hs - 24 * dt) / hs;
      this.velocity.x *= k; this.velocity.z *= k;
    }
    if (this.grounded && wl < 0.1) {
      this.velocity.x *= Math.max(0, 1 - 8 * dt);
      this.velocity.z *= Math.max(0, 1 - 8 * dt);
    }

    if (wantJump && this.grounded && this.jumpTimer <= 0) {
      this.velocity.y = 9.5;
      this.grounded = false;
      this.jumpTimer = 1.1 + Math.random();
      this.jetTimer = 0.3;
    }
    this.jetting = false;
    if ((wantJet || this.jetTimer > 0) && !this.grounded && this.fuel > 0.5) {
      this.velocity.y += 40 * dt;
      if (this.velocity.y > 7.6) this.velocity.y = 7.6;
      this.fuel -= 25 * dt;
      this.jetting = true;
      this.trailTimer -= dt;
      if (this.trailTimer <= 0) {
        this.trailTimer = 0.045;
        const p = this.position.clone().add(new THREE.Vector3((Math.random() - 0.5) * 0.5, 0.9, (Math.random() - 0.5) * 0.5));
        game.effects.jet(p, new THREE.Vector3(0, -1, 0), Math.random() > 0.4 ? this.color : 0xffa040);
      }
    }
    if (this.grounded) this.fuel = Math.min(100, this.fuel + 22 * dt);

    // stuck detection
    const beforeX = this.position.x, beforeZ = this.position.z;
    moveBody(this, world, dt, { stepHeight: 0.7, gravity: 26 });
    if (wl > 0.3) {
      const moved = Math.hypot(this.position.x - beforeX, this.position.z - beforeZ);
      if (moved < 0.15 * dt * 60 * 0.016) {
        this.stuckTimer += dt;
        if (this.stuckTimer > 0.35) {
          this.stuck = true;
          this.jetTimer = 0.5;
          this.strafeDir *= -1;
          this.stuckTimer = 0;
        }
      } else {
        this.stuckTimer = Math.max(0, this.stuckTimer - dt);
        this.stuck = false;
      }
    }

    if (this.position.y < -20) {
      game.kill(this, null, 'void');
      return;
    }

    // pickups (health / armor only; ammo irrelevant for bots)
    for (const p of world.pickups) {
      if (!p.active) continue;
      if (p.type === 'quad') continue;
      const dx = p.position.x - this.position.x;
      const dz = p.position.z - this.position.z;
      const dy = p.position.y - (this.position.y + 1.0);
      if (dx * dx + dz * dz < 2.3 * 2.3 && Math.abs(dy) < 2.2) game.collectPickup(p, this);
    }

    // ---------- shoot ----------
    if (t && t.alive && canSee && this.fireTimer <= 0 && tDist < 52 && this.protection < 0.1) {
      const aim = this.aimAt(t, tDist);
      const angleOk = true;
      if (angleOk) {
        game.botFire(this, aim, tDist);
        this.fireTimer = this.rate * (0.85 + Math.random() * 0.4);
        // recoil lean
        this.model.position.z -= 0.02;
      }
    }

    // ---------- animate / orient ----------
    const desiredYaw = t && t.alive && tDist < 55
      ? Math.atan2(-(t.position.x - this.position.x), -(t.position.z - this.position.z))
      : (hs > 0.5 ? Math.atan2(-this.velocity.x, -this.velocity.z) : this.yaw);
    let dy = desiredYaw - this.yaw;
    while (dy > Math.PI) dy -= Math.PI * 2;
    while (dy < -Math.PI) dy += Math.PI * 2;
    this.yaw += dy * Math.min(1, dt * 7);
    this.model.rotation.y = this.yaw;
    this.model.position.copy(this.position);

    const walk = Math.min(1, hs / 7);
    const swing = Math.sin(game.time * 9 + this.id) * walk;
    this.legs[0].rotation.x = swing * 0.6;
    this.legs[1].rotation.x = -swing * 0.6;
    this.arms[0].rotation.x = -swing * 0.25;
    this.arms[1].rotation.x = swing * 0.25 - 0.15;
    this.bodyGroup.position.y = Math.abs(Math.cos(game.time * 9 + this.id)) * 0.04 * walk;
    this.bodyGroup.rotation.x = THREE.MathUtils.lerp(this.bodyGroup.rotation.x, this.jetting ? 0.22 : walk * 0.06, Math.min(1, dt * 5));
    this.bodyGroup.rotation.z = this.jetting ? Math.sin(game.time * 6) * 0.05 : 0;

    // jet flames
    const flameScale = this.jetting ? 0.55 + Math.random() * 0.35 : 0;
    for (const f of [this.flameL, this.flameR]) {
      f.material.opacity = this.jetting ? 0.85 : 0;
      f.scale.setScalar(flameScale);
    }
    // tag fade with distance
    if (game.player) {
      const d = this.position.distanceTo(game.player.position);
      this.tag.material.opacity = THREE.MathUtils.clamp(1.4 - d / 55, 0, 0.95);
      this.tag.scale.set(2.0 + d * 0.012, (2.0 + d * 0.012) * 0.25, 1);
    }
    this.aura.material.opacity = 0.14 + (this.protection > 0 ? 0.3 : 0) + Math.sin(game.time * 3 + this.id) * 0.05;
    this.weaponGlow.rotation.z += dt * 8;
    if (this.aimTimer <= 0) {
      this.aimTimer = 0.2;
      this.aimError.set((Math.random() - 0.5) * this.spread, (Math.random() - 0.5) * this.spread * 0.6, (Math.random() - 0.5) * this.spread);
    }
  }

  aimAt(target, dist) {
    const eye = this.eyePosition;
    const tp = target.eyePosition;
    const speed = 40;
    const lead = Math.min(0.75, dist / speed);
    const predicted = tp.clone().addScaledVector(target.velocity, lead * 0.85);
    // gravity compensation for projectile arc
    predicted.y += 0.5 * 3.4 * (dist / speed) * (dist / speed);
    const dir = predicted.sub(eye).normalize();
    const err = 0.02 + (1 - this.skill) * 0.05 + dist * 0.0009;
    dir.x += (Math.random() - 0.5) * err * 2;
    dir.y += (Math.random() - 0.5) * err;
    dir.z += (Math.random() - 0.5) * err * 2;
    return dir.normalize();
  }

  resetScores() {
    this.score = 0; this.deaths = 0; this.streak = 0; this.bestStreak = 0; this.quad = 0;
  }
}

export function createBots(scene) {
  return BOT_DEFS.map((d, i) => {
    const b = new Bot(d, i);
    b.addTo(scene);
    return b;
  });
}

import { WEAPONS } from './weapons.js';

const $ = (id) => document.getElementById(id);

export class HUD {
  constructor() {
    this.root = $('hud');
    this.healthVal = $('healthVal');
    this.healthBar = $('healthBar');
    this.armorVal = $('armorVal');
    this.armorBar = $('armorBar');
    this.fuelBar = $('fuelBar');
    this.weaponName = $('weaponName');
    this.weaponHint = $('weaponHint');
    this.ammoVal = $('ammoVal');
    this.ammoLabel = $('ammoLabel');
    this.clock = $('clock');
    this.fragLimit = $('fragLimit');
    this.killfeedEl = $('killfeed');
    this.announceEl = $('announce');
    this.crosshair = $('crosshair');
    this.hitmarkerEl = $('hitmarker');
    this.hitmarkerKillEl = $('hitmarkerKill');
    this.targetTag = $('targetTag');
    this.targetName = $('targetName');
    this.targetHp = $('targetHp');
    this.vignette = $('vignette');
    this.damageFx = $('damageFx');
    this.quadFx = $('quadFx');
    this.quadTimer = $('quadTimer');
    this.quadState = $('quadState');
    this.objective = document.querySelector('.objective');
    this.playerFrags = $('playerFrags');
    this.playerDeaths = $('playerDeaths');
    this.playerStreak = $('playerStreak');
    this.respawnOverlay = $('respawnOverlay');
    this.respawnTitle = $('respawnTitle');
    this.respawnSub = $('respawnSub');
    this.respawnCount = $('respawnCount');
    this.scoreboardEl = $('scoreboard');
    this.sbClock = $('sbClock');
    this.sbRows = $('sbRows');
    this.radar = $('radar');
    this.radarCount = $('radarCount');
    this.radarCtx = this.radar.getContext('2d');
    this.pointerHint = $('pointerHint');
    this.touchControls = $('touchControls');
    this.slots = Array.from(document.querySelectorAll('.slot'));
    this.weaponPanel = document.querySelector('.weapon-panel');
    this.vitals = document.querySelector('.vitals');
    this.announceTimer = null;
    this.killRows = [];
    this.scoreboardTimer = 0;
    this.radarAngle = 0;
    this.lastAim = null;
    this.toastEl = $('toast');
    this.toastTimer = null;
    this.weaponFlash = 0;
    this.slotButtons = [];
    this.bindSlotButtons();
  }

  bindSlotButtons() {
    this.slots.forEach((s) => {
      s.addEventListener('pointerdown', (e) => {
        e.preventDefault();
        this.onSlot?.(Number(s.dataset.slot));
      });
    });
  }

  setVisible(v) {
    this.root.classList.toggle('hidden', !v);
  }

  flashWeapon() {
    this.weaponFlash = 1;
    this.weaponPanel.style.transition = 'none';
    this.weaponPanel.style.transform = 'translateY(6px)';
    requestAnimationFrame(() => {
      this.weaponPanel.style.transition = 'transform .22s cubic-bezier(.2,.9,.3,1.4)';
      this.weaponPanel.style.transform = '';
    });
  }

  update(dt, game) {
    const p = game.player;
    this.weaponFlash = Math.max(0, this.weaponFlash - dt * 4);

    // vitals
    const hp = Math.max(0, Math.round(p.health));
    const ar = Math.max(0, Math.round(p.armor));
    this.healthVal.textContent = hp;
    this.armorVal.textContent = ar;
    this.healthBar.style.width = Math.min(100, hp / 100 * 100) + '%';
    this.armorBar.style.width = Math.min(100, ar / 100 * 100) + '%';
    this.vitals.classList.toggle('low', hp <= 30);

    // fuel
    const fuelPct = p.fuel / p.maxFuel * 100;
    this.fuelBar.style.width = fuelPct + '%';
    this.fuelBar.classList.toggle('low', fuelPct < 28);
    const skiTag = $('skiTag');
    skiTag.textContent = p.jetting ? 'JET ACTIVE' : p.skiing ? 'SKIING' : p.grounded && Math.hypot(p.velocity.x, p.velocity.z) > 8 ? 'MOMENTUM' : p.fuel < 25 ? 'FUEL LOW' : 'SKI READY';
    skiTag.classList.toggle('hot', p.jetting || p.skiing || Math.hypot(p.velocity.x, p.velocity.z) > 8);

    // weapon
    const w = WEAPONS[p.weaponIndex];
    this.weaponName.textContent = w.name;
    this.weaponHint.textContent = w.infinite ? '∞ AMMO · ' + w.desc : w.desc;
    const ammo = p.ammo[w.id];
    this.ammoVal.textContent = w.infinite ? '∞' : ammo;
    this.ammoLabel.textContent = w.ammoLabel;
    this.ammoVal.style.color = !w.infinite && ammo <= 2 ? '#ff6b7a' : '';
    const reloadTag = $('reloadTag');
    reloadTag.textContent = !w.infinite && ammo <= 0 ? 'EMPTY' : '';
    this.slots.forEach((s, i) => {
      const sw = WEAPONS[i];
      const a = p.ammo[sw.id];
      const full = sw.maxAmmo || 1;
      s.classList.toggle('active', i === p.weaponIndex);
      s.classList.toggle('empty', !sw.infinite && a <= 0);
      s.style.setProperty('--f', sw.infinite ? 1 : Math.max(0, Math.min(1, a / full)));
    });

    // crosshair
    const speed = Math.hypot(p.velocity.x, p.velocity.z);
    const spread = 5 + speed * 0.7 + (p.grounded ? 0 : 5) + (p.jetting ? 3 : 0);
    this.crosshair.style.setProperty('--spread', spread.toFixed(1) + 'px');
    this.crosshair.classList.toggle('quad', p.quad > 0);

    // quad objective
    const quadPickup = game.world.pickups.find(x => x.type === 'quad');
    if (p.quad > 0) {
      this.objective.classList.add('live');
      this.quadState.textContent = 'ACTIVE · ' + Math.ceil(p.quad) + 's';
      this.quadTimer.style.width = (p.quad / 30 * 100) + '%';
      this.quadFx.classList.add('on');
    } else {
      this.quadFx.classList.remove('on');
      if (quadPickup) {
        if (quadPickup.active) {
          this.objective.classList.add('live');
          this.quadState.textContent = 'AVAILABLE · CENTER';
          this.quadTimer.style.width = '100%';
        } else {
          this.objective.classList.remove('live');
          this.quadState.textContent = 'RESPAWN ' + Math.ceil(quadPickup.timer) + 's';
          this.quadTimer.style.width = '0%';
        }
      }
    }

    // damage flash
    this.damageFx.style.opacity = (p.damageFlash * 0.85).toFixed(2);
    const lowHp = p.health < 35 && p.alive ? (0.12 + Math.sin(game.time * 6) * 0.05) : 0;
    this.vignette.style.boxShadow = p.quad > 0 ? 'inset 0 0 140px rgba(255,176,46,.35)' : lowHp ? `inset 0 0 130px rgba(255,20,50,${lowHp})` : '';

    // scores
    this.playerFrags.textContent = p.score;
    this.playerDeaths.textContent = p.deaths;
    this.playerStreak.textContent = p.streak;

    // clock
    const t = Math.max(0, game.timeLeft);
    const mm = Math.floor(t / 60).toString().padStart(2, '0');
    const ss = Math.floor(t % 60).toString().padStart(2, '0');
    this.clock.textContent = mm + ':' + ss;
    this.sbClock.textContent = mm + ':' + ss;
    this.fragLimit.textContent = game.fragLimit;

    // aim target tag
    const aim = game.aimTarget;
    if (aim && aim.alive && aim !== p) {
      this.targetTag.classList.remove('hidden');
      this.targetName.textContent = aim.name;
      this.targetHp.style.width = Math.max(0, (aim.health / 100) * 100) + '%';
    } else {
      this.targetTag.classList.add('hidden');
    }

    // scoreboard interval
    this.scoreboardTimer -= dt;
    if (this.scoreboardTimer <= 0) {
      this.scoreboardTimer = 0.4;
      if (!this.scoreboardEl.classList.contains('hidden')) this.renderScoreboard(game);
      this.radarAngle += 0.5;
    }

    this.drawRadar(game);

    // respawn overlay countdown
    if (!p.alive && game.respawnTimer > 0) {
      this.respawnCount.textContent = Math.ceil(game.respawnTimer);
    }

    // weapon switch flash
    if (this.weaponFlash > 0) {
      this.weaponPanel.style.filter = `brightness(${1 + this.weaponFlash * 0.5})`;
    } else this.weaponPanel.style.filter = '';
  }

  drawRadar(game) {
    const ctx = this.radarCtx;
    const W = this.radar.width, H = this.radar.height;
    const cx = W / 2, cy = H / 2;
    const p = game.player;
    const scale = 1.65;
    ctx.clearRect(0, 0, W, H);
    ctx.save();
    ctx.beginPath();
    ctx.arc(cx, cy, W / 2 - 2, 0, Math.PI * 2);
    ctx.clip();

    // background
    const bg = ctx.createRadialGradient(cx, cy, 10, cx, cy, W / 2);
    bg.addColorStop(0, 'rgba(12,30,44,.82)');
    bg.addColorStop(1, 'rgba(4,7,16,.7)');
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, W, H);

    const yaw = p.yaw;
    const fx = -Math.sin(yaw), fz = -Math.cos(yaw);
    const rx = Math.cos(yaw), rz = -Math.sin(yaw);
    const tp = (x, z) => {
      const dx = (x - p.position.x), dz = (z - p.position.z);
      return [cx + (dx * rx + dz * rz) * scale, cy - (dx * fx + dz * fz) * scale];
    };

    // grid
    ctx.strokeStyle = 'rgba(63,233,255,.08)';
    ctx.lineWidth = 1;
    for (let i = -4; i <= 4; i++) {
      ctx.beginPath(); ctx.moveTo(cx + i * 22, 0); ctx.lineTo(cx + i * 22, H); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(0, cy + i * 22); ctx.lineTo(W, cy + i * 22); ctx.stroke();
    }

    // map structures
    ctx.strokeStyle = 'rgba(120,195,225,.26)';
    ctx.fillStyle = 'rgba(40,80,110,.2)';
    ctx.lineWidth = 1;
    for (const b of game.world.colliders) {
      const w = b.max.x - b.min.x, d = b.max.z - b.min.z;
      if (w * d < 4 || b.min.y > 12) continue;
      const pts = [
        tp(b.min.x, b.min.z), tp(b.max.x, b.min.z), tp(b.max.x, b.max.z), tp(b.min.x, b.max.z)
      ];
      ctx.beginPath();
      ctx.moveTo(pts[0][0], pts[0][1]);
      for (let i = 1; i < 4; i++) ctx.lineTo(pts[i][0], pts[i][1]);
      ctx.closePath();
      ctx.fill();
      ctx.stroke();
    }

    // pickups
    for (const pu of game.world.pickups) {
      if (!pu.active) continue;
      const [x, y] = tp(pu.position.x, pu.position.z);
      if (Math.hypot(x - cx, y - cy) > W / 2 - 4) continue;
      ctx.fillStyle = pu.type === 'quad' ? '#ffb02e' : pu.type === 'health' || pu.type === 'mega' ? '#ff4c6a' : pu.type === 'armor' ? '#51ffb0' : '#8bb8d8';
      ctx.fillRect(x - 1.5, y - 1.5, 3, 3);
    }

    // enemies
    let count = 0;
    for (const b of game.bots) {
      if (!b.alive) continue;
      count++;
      const [x, y] = tp(b.position.x, b.position.z);
      const d = Math.hypot(x - cx, y - cy);
      if (d > W / 2 - 6) continue;
      ctx.fillStyle = '#' + b.color.toString(16).padStart(6, '0');
      ctx.shadowColor = ctx.fillStyle;
      ctx.shadowBlur = 6;
      ctx.beginPath();
      ctx.arc(x, y, 3.4, 0, Math.PI * 2);
      ctx.fill();
      ctx.shadowBlur = 0;
    }
    this.radarCount.textContent = count + ' HOSTILES';

    // sweep
    const a = this.radarAngle;
    const grad = ctx.createConicGradient ? ctx.createConicGradient(a, cx, cy) : null;
    ctx.strokeStyle = 'rgba(63,233,255,.25)';
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.lineTo(cx + Math.cos(a) * W / 2, cy + Math.sin(a) * W / 2);
    ctx.stroke();

    // player arrow
    ctx.translate(cx, cy);
    ctx.fillStyle = '#c9fbff';
    ctx.shadowColor = '#3fe9ff';
    ctx.shadowBlur = 8;
    ctx.beginPath();
    ctx.moveTo(0, -7); ctx.lineTo(5, 5); ctx.lineTo(0, 2); ctx.lineTo(-5, 5);
    ctx.closePath();
    ctx.fill();
    ctx.restore();

    // ring
    ctx.strokeStyle = 'rgba(63,233,255,.3)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(cx, cy, W / 2 - 2, 0, Math.PI * 2);
    ctx.stroke();
  }

  killfeed(killer, victim, weaponId, quad = false) {
    const row = document.createElement('div');
    row.className = 'kf-row' + (quad ? ' quad' : '');
    const w = WEAPONS.find(x => x.id === weaponId);
    const icon = weaponId === 'rail' ? '⌁' : weaponId === 'rocket' ? '✸' : weaponId === 'spin' ? '◎' : '✶';
    row.innerHTML = `<b class="${killer === 'YOU' ? 'you' : ''}">${killer}</b><i>${icon}</i><b class="${victim === 'YOU' ? 'you' : ''}">${victim}</b><span class="wep">${w ? w.short : (weaponId === 'void' ? 'VOID' : 'FRAG')}</span>`;
    this.killfeedEl.appendChild(row);
    this.killRows.push({ el: row, t: 7 });
    if (this.killRows.length > 5) {
      const old = this.killRows.shift();
      old.el.remove();
    }
    // purge
    const now = performance.now();
    for (let i = this.killRows.length - 1; i >= 0; i--) {
      const k = this.killRows[i];
      if (!k.start) k.start = now;
      if (now - k.start > 7000) {
        k.el.style.transition = 'opacity .4s';
        k.el.style.opacity = '0';
        setTimeout(() => k.el.remove(), 420);
        this.killRows.splice(i, 1);
      }
    }
  }

  announce(text, variant = '', dur = 2200) {
    const el = this.announceEl;
    el.textContent = text;
    el.className = 'announce ' + variant;
    void el.offsetWidth;
    el.classList.add('show');
    clearTimeout(this.announceTimer);
    this.announceTimer = setTimeout(() => el.classList.remove('show'), dur);
  }

  hitmarker(kill) {
    const el = kill ? this.hitmarkerKillEl : this.hitmarkerEl;
    el.classList.remove('show');
    void el.offsetWidth;
    el.classList.add('show');
  }

  damage(sourcePos, player) {
    const wrap = document.getElementById('damageDirs');
    const el = document.createElement('div');
    el.className = 'dmg-dir';
    let angle = 0;
    if (sourcePos) {
      const dx = sourcePos.x - player.position.x;
      const dz = sourcePos.z - player.position.z;
      const worldAngle = Math.atan2(dx, dz);
      // relative to camera forward (-sin yaw, -cos yaw)
      angle = worldAngle - (player.yaw + Math.PI);
    }
    el.style.setProperty('--r', angle + 'rad');
    el.style.transform = `rotate(${angle + Math.PI}rad) translateY(-110px)`;
    wrap.appendChild(el);
    setTimeout(() => el.remove(), 850);
  }

  toast(text) {
    this.toastEl.textContent = text;
    this.toastEl.classList.remove('hidden');
    clearTimeout(this.toastTimer);
    this.toastTimer = setTimeout(() => this.toastEl.classList.add('hidden'), 1600);
  }

  showRespawn(killer, cause) {
    this.respawnOverlay.classList.remove('hidden');
    this.respawnTitle.textContent = cause === 'void' ? 'LOST TO THE VOID' : 'YOU WERE FRIED';
    this.respawnSub.textContent = killer ? 'BY ' + killer : (cause === 'void' ? 'NOBODY HEARD YOU' : 'BY THE ARENA');
  }
  hideRespawn() { this.respawnOverlay.classList.add('hidden'); }

  toggleScoreboard(show) {
    this.scoreboardEl.classList.toggle('hidden', !show);
  }

  renderScoreboard(game) {
    const list = [...game.combatants].sort((a, b) => b.score - a.score || a.deaths - b.deaths);
    const colors = ['#3fe9ff', '#ff2e8a', '#ffb02e', '#51ffb0', '#d9e8ff'];
    this.sbRows.innerHTML = list.map((e, i) => {
      const color = e.isPlayer ? '#3fe9ff' : '#' + e.color.toString(16).padStart(6, '0');
      return `<div class="sb-row ${e.isPlayer ? 'you' : ''}">
        <span class="sb-rank">${String(i + 1).padStart(2, '0')}</span>
        <span class="sb-name"><i style="color:${color};background:${color}"></i>${e.name}${e.isPlayer ? ' <em style="font-style:normal;color:#658399">(YOU)</em>' : ''}</span>
        <span class="sb-frags">${e.score}</span>
        <span>${e.deaths}</span>
        <span>${e.streak || 0}</span>
      </div>`;
    }).join('');
  }

  showPointerHint(show) {
    this.pointerHint.classList.toggle('hidden', !show);
  }

  showGameOver(game, victory) {
    const el = document.getElementById('gameover');
    const card = el.querySelector('.go-card');
    card.classList.toggle('lost', !victory);
    const title = document.getElementById('goTitle');
    const eyebrow = document.getElementById('goEyebrow');
    const sub = document.getElementById('goSub');
    const sorted = [...game.combatants].sort((a, b) => b.score - a.score || a.deaths - b.deaths);
    const rank = sorted.findIndex(e => e.isPlayer) + 1;
    title.textContent = victory ? 'VICTORY' : (rank <= 2 ? 'SO CLOSE' : 'DEFEAT');
    eyebrow.innerHTML = `<i></i> MATCH COMPLETE · RANK ${rank} / ${sorted.length}`;
    sub.textContent = victory
      ? 'Frag limit reached. The arena remembers.'
      : `The match slipped away. ${game.player.score} frags, ${game.player.deaths} deaths.`;
    document.getElementById('goScore').innerHTML = `
      <div><b>${game.player.score}</b>YOUR FRAGS</div>
      <div><b>${game.player.deaths}</b>DEATHS</div>
      <div><b>${game.player.bestStreak}</b>BEST STREAK</div>
      <div><b>${sorted[0] ? sorted[0].name : '—'}</b>LEADER</div>`;
    document.getElementById('goRows').innerHTML = sorted.map((e, i) => {
      const color = e.isPlayer ? '#3fe9ff' : '#' + e.color.toString(16).padStart(6, '0');
      return `<div class="go-row ${e.isPlayer ? 'you' : ''}"><span>${i + 1}</span><span style="color:${e.isPlayer ? '#eafcff' : color}">${e.name}</span><b>${e.score}</b><span>${e.deaths}</span></div>`;
    }).join('');
    el.classList.remove('hidden');
  }
  hideGameOver() { document.getElementById('gameover').classList.add('hidden'); }
}

import * as THREE from 'three';
import { World } from './world.js';
import { Player } from './player.js';
import { createBots } from './bots.js';
import { Effects } from './fx.js';
import { AudioEngine } from './audio.js';
import { Input } from './input.js';
import { HUD } from './hud.js';
import { ViewModel, WEAPONS } from './weapons.js';
import { glowTexture } from './textures.js';

const $ = (id) => document.getElementById(id);
const UP = new THREE.Vector3(0, 1, 0);

class Game {
  constructor() {
    this.canvas = $('game');
    this.renderer = new THREE.WebGLRenderer({ canvas: this.canvas, antialias: true, powerPreference: 'high-performance', alpha: false });
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.75));
    this.renderer.setSize(window.innerWidth, window.innerHeight);
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.12;
    this.renderer.shadowMap.enabled = true;
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    this.renderer.autoClear = false;

    this.scene = new THREE.Scene();
    this.camera = new THREE.PerspectiveCamera(78, window.innerWidth / window.innerHeight, 0.08, 900);
    this.camera.rotation.order = 'YXZ';
    this.scene.add(this.camera);

    this.world = new World(this.scene);
    this.effects = new Effects(this.scene);
    this.audio = new AudioEngine();
    this.hud = new HUD();
    this.player = new Player();
    this.bots = createBots(this.scene);
    this.combatants = [this.player, ...this.bots];
    this.viewModel = new ViewModel(window.innerWidth / window.innerHeight);
    this.viewModel.setAspect(this.camera.aspect);
    this.effects.setViewport(window.innerHeight, 78);

    this.state = 'menu';
    this.time = 0;
    this.timeLeft = 300;
    this.fragLimit = 20;
    this.respawnTimer = 0;
    this.over = false;
    this.firstBlood = true;
    this.projectiles = [];
    this.recoil = 0;
    this.sensitivity = Number(localStorage.getItem('tribes_sens') || 1);
    this.reducedMotion = false;
    this.deathCam = 0;
    this.aimTarget = null;
    this.menuAngle = 0.5;
    this.playerKills = [];
    this.lastTab = false;
    this.pointerHintTimer = 0;
    this.shake = 0;
    this.quadWasActive = false;
    this.menuBotsReady = false;

    this.input = new Input(this.canvas, {
      onPause: () => this.handleEscape(),
      onLockChange: (locked) => {
        if (this.state === 'playing') this.hud.showPointerHint(!locked && !this.input.isTouch);
      },
      onWeapon: () => {
        if (this.state === 'playing' && this.player.alive) {
          this.player.selectWeapon((this.player.weaponIndex + 1) % WEAPONS.length, this);
        }
      }
    });
    this.hud.onSlot = (i) => {
      if (this.state === 'playing' && this.player.alive) this.player.selectWeapon(i, this);
    };

    this.projectileMats = {
      rocket: new THREE.MeshBasicMaterial({ color: 0xffb060 }),
      rocketGlow: glowTexture('rgba(255,250,220,1)', 'rgba(255,160,60,.7)', 'rgba(255,80,0,0)'),
      spin: new THREE.MeshBasicMaterial({ color: 0x7de8ff }),
      spinGlow: glowTexture('rgba(220,255,255,1)', 'rgba(70,200,255,.6)', 'rgba(0,120,255,0)'),
    };

    this.bindUI();
    this.arrangeMenu();
    this.hideBoot();
    this.addEventListeners();
  }

  hideBoot() {
    setTimeout(() => {
      const b = $('boot');
      b.classList.add('done');
      setTimeout(() => b.classList.add('hidden'), 550);
    }, 500);
  }

  bindUI() {
    $('playBtn').addEventListener('click', () => {
      this.audio.init();
      this.audio.uiBig();
      this.startMatch();
    });
    $('controlsBtn').addEventListener('click', () => {
      this.audio.init(); this.audio.ui();
      $('controlsPanel').classList.toggle('hidden');
    });
    $('controlsClose').addEventListener('click', () => $('controlsPanel').classList.add('hidden'));

    $('resumeBtn').addEventListener('click', () => { this.audio.init(); this.audio.ui(); this.resume(); });
    $('restartBtn').addEventListener('click', () => { this.audio.init(); this.audio.ui(); this.startMatch(); });
    $('quitBtn').addEventListener('click', () => this.quitToMenu());
    $('againBtn').addEventListener('click', () => { this.audio.init(); this.audio.ui(); this.startMatch(); });
    $('menuBtn').addEventListener('click', () => this.quitToMenu());

    const sens = $('sensSlider');
    const sensVal = $('sensVal');
    const pauseSens = $('pauseSens');
    const pauseSensVal = $('pauseSensVal');
    const applySens = (v) => {
      this.sensitivity = v;
      localStorage.setItem('tribes_sens', v);
      sens.value = v; pauseSens.value = v;
      sensVal.textContent = Number(v).toFixed(2);
      pauseSensVal.textContent = Number(v).toFixed(2);
    };
    applySens(this.sensitivity);
    sens.addEventListener('input', () => applySens(Number(sens.value)));
    pauseSens.addEventListener('input', () => applySens(Number(pauseSens.value)));

    const soundLabel = (b) => b.textContent = 'SOUND: ' + (this.audio.muted ? 'OFF' : 'ON');
    const toggleSound = () => {
      this.audio.init();
      this.audio.setMuted(!this.audio.muted);
      soundLabel($('soundBtn')); soundLabel($('pauseSoundBtn'));
      this.hud.toast(this.audio.muted ? 'AUDIO MUTED' : 'AUDIO ONLINE');
    };
    $('soundBtn').addEventListener('click', toggleSound);
    $('pauseSoundBtn').addEventListener('click', toggleSound);
    soundLabel($('soundBtn')); soundLabel($('pauseSoundBtn'));

    // mobile detection
    this.isTouch = this.input.isTouch;
    if (this.isTouch) document.body.classList.add('touch');

    this.canvas.addEventListener('pointerdown', () => {
      this.audio.init();
      if (this.state === 'playing' && this.player.alive && !this.input.isTouch) this.input.requestLock();
    });

    // icon rendering of ammo etc.
    this.hud.setVisible(false);
  }

  addEventListeners() {
    window.addEventListener('resize', () => {
      const w = window.innerWidth, h = window.innerHeight;
      this.renderer.setSize(w, h);
      this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.75));
      this.camera.aspect = w / h;
      this.camera.updateProjectionMatrix();
      this.viewModel.setAspect(w / h);
      this.effects.setViewport(h, 78);
    });
    document.addEventListener('visibilitychange', () => {
      if (document.hidden && this.state === 'playing') this.pause();
    });
  }

  arrangeMenu() {
    this.state = 'menu';
    this.hud.setVisible(false);
    this.input.enabled = false;
    this.input.releaseLock();
    $('menu').classList.remove('hidden');
    $('pause').classList.add('hidden');
    $('gameover').classList.add('hidden');
    $('controlsPanel').classList.add('hidden');
    this.world.resetPickups();
    // pose bots around arena for the attract shot
    const spots = [14, 22, 6, 10];
    this.bots.forEach((b, i) => {
      const sp = this.world.spawnPoints[spots[i] % this.world.spawnPoints.length];
      b.spawn(this.world, sp);
      b.protection = 999;
      b.tag.material.opacity = 0;
      b.aura.material.opacity = 0.1;
    });
    this.player.alive = false;
    this.menuAngle = 0.55;
    this.camera.position.set(38, 17, 34);
    this.camera.lookAt(0, 4, 0);
  }

  startMatch() {
    this.audio.init();
    this.audio.setIntensity(0.75);
    this.audio.matchStart();
    $('menu').classList.add('hidden');
    $('pause').classList.add('hidden');
    $('gameover').classList.add('hidden');
    $('controlsPanel').classList.add('hidden');
    this.hud.hideGameOver();
    this.hud.setVisible(true);
    this.hud.hideRespawn();
    this.hud.toggleScoreboard(false);
    this.state = 'playing';
    this.input.enabled = true;
    this.timeLeft = 300;
    this.fragLimit = 20;
    this.respawnTimer = 0;
    this.over = false;
    this.firstBlood = true;
    this.deathCam = 0;
    this.recoil = 0;
    this.shake = 0;
    this.playerKills = [];
    this.projectiles.forEach(p => this.removeProjectile(p));
    this.projectiles.length = 0;
    this.effects.clearGibs();
    this.world.resetPickups();

    this.player.reset();
    const start = this.world.spawnPoints.find(s => s.pos.z > 28 && Math.abs(s.pos.x) < 1) || this.world.spawnPoints[0];
    this.player.spawn(this.world, start);
    this.player.pitch = 0;
    this.player.yaw = start.yaw;
    this.viewModel.show(0, true);

    // spawn bots far from player
    const sorted = [...this.world.spawnPoints].sort((a, b) => b.pos.distanceTo(this.player.position) - a.pos.distanceTo(this.player.position));
    this.bots.forEach((b, i) => {
      b.resetScores();
      b.spawn(this.world, sorted[(i + 1) % sorted.length]);
      b.tag.material.opacity = 0.9;
      this.spawnFlash(b.position, b.color);
    });

    this.camera.position.copy(this.player.eyePosition);
    this.camera.rotation.set(this.player.pitch, this.player.yaw, 0);
    this.hud.announce('FIGHT', 'gold', 1900);
    this.audio.matchStart();
    if (!this.input.isTouch) {
      this.input.requestLock();
      this.hud.showPointerHint(true);
      this.pointerHintTimer = 2.5;
    }
  }

  spawnFlash(pos, color) {
    this.effects.burst(pos.clone().setY(pos.y + 0.4), 20, { color, speed: 4.5, size: 0.24, life: 0.6, grav: 2 });
    this.effects.ring?.(pos, color);
  }

  pause() {
    if (this.state !== 'playing') return;
    this.state = 'paused';
    this.input.enabled = false;
    this.input.releaseLock();
    this.audio.setJet(false);
    const sorted = [...this.combatants].sort((a, b) => b.score - a.score);
    $('pauseFrags').textContent = this.player.score;
    $('pauseLeader').textContent = sorted[0] ? sorted[0].name : '—';
    const tips = [
      'TIP: JETPACK UP, CUT THE JETS, AND FIRE ON THE WAY DOWN.',
      'TIP: HOLD SHIFT TO SKI — KEEP YOUR SPEED THROUGH THE LANES.',
      'TIP: A ROCKET AT YOUR FEET IS FASTER THAN WALKING.',
      'TIP: THE QUAD CORE RESPAWNS 38 SECONDS AFTER PICKUP.',
      'TIP: FALLING OFF THE ARENA COUNTS AS A DEATH. THE VOID IS PATIENT.'
    ];
    $('pauseTip').textContent = tips[(Math.random() * tips.length) | 0];
    $('pause').classList.remove('hidden');
    this.hud.showPointerHint(false);
  }

  resume() {
    if (this.state !== 'paused') return;
    $('pause').classList.add('hidden');
    this.state = 'playing';
    this.input.enabled = true;
    this.input.requestLock();
    this.hud.showPointerHint(!this.input.locked && !this.input.isTouch);
  }

  handleEscape() {
    if (this.state === 'playing') this.pause();
    else if (this.state === 'paused') this.resume();
  }

  quitToMenu() {
    this.state = 'menu';
    this.input.enabled = false;
    this.input.releaseLock();
    this.audio.setJet(false);
    this.audio.setIntensity(0.35);
    this.hud.setVisible(false);
    this.hud.toggleScoreboard(false);
    $('pause').classList.add('hidden');
    $('gameover').classList.add('hidden');
    $('menu').classList.remove('hidden');
    this.projectiles.forEach(p => this.removeProjectile(p));
    this.projectiles.length = 0;
    this.effects.clearGibs();
    this.arrangeMenu();
  }

  // ---------------- combat ----------------
  raySphere(origin, dir, center, radius) {
    const ox = center.x - origin.x, oy = center.y - origin.y, oz = center.z - origin.z;
    const t = ox * dir.x + oy * dir.y + oz * dir.z;
    if (t < 0) return null;
    const d2 = ox * ox + oy * oy + oz * oz - t * t;
    const r2 = radius * radius;
    if (d2 > r2) return null;
    return t - Math.sqrt(r2 - d2);
  }

  entityCenter(e) {
    return new THREE.Vector3(e.position.x, e.position.y + (e.isPlayer ? 1.05 : 1.05), e.position.z);
  }

  firePlayerWeapon(player, w) {
    player.lastWeaponId = w.id;
    this.audio[w.id === 'scatter' ? 'shotgun' : w.id === 'rocket' ? 'rocket' : w.id === 'rail' ? 'rail' : 'spin']();
    this.viewModel.fire();
    this.recoil = Math.min(1.2, this.recoil + (w.kick || 1));
    if (!w.infinite) player.ammo[w.id] = Math.max(0, player.ammo[w.id] - 1);

    const origin = player.eyePosition;
    const forward = player.forward;
    const muzzle = origin.clone().addScaledVector(forward, 0.75).addScaledVector(player.flatRight, 0.26).add(new THREE.Vector3(0, -0.14, 0));
    const quadMult = player.quad > 0 ? 4 : 1;

    if (w.id === 'scatter') {
      let anyHit = false;
      for (let i = 0; i < w.pellets; i++) {
        const spread = w.spread;
        const rx = (Math.random() - 0.5) * 2 * spread;
        const ry = (Math.random() - 0.5) * 2 * spread;
        const dir = forward.clone().addScaledVector(player.flatRight, rx).addScaledVector(UP, ry).normalize();
        const res = this.hitscan(origin, dir, w.range, w.damage * quadMult, player, w.id, false);
        if (i % 3 === 0) {
          this.effects.beam(muzzle, res.point, 0xffcf8a, 0.018, 0.055);
        }
        if (res.target) anyHit = true;
      }
      this.audio.shotgun();
      if (anyHit) this.hud.hitmarker(false);
    } else if (w.id === 'rail') {
      const res = this.hitscan(origin, forward, w.range, w.damage * quadMult, player, w.id, true);
      const end = res.point.clone().addScaledVector(forward, -0.15);
      this.effects.rail(muzzle, end);
      if (res.target) {
        this.hud.hitmarker(false);
        this.effects.burst(res.point, 14, { color: 0x9dfbff, speed: 5, size: 0.18, life: 0.35, grav: 3 });
      }
      this.shake = Math.max(this.shake, 0.4);
    } else {
      this.spawnProjectile(player, w, origin, forward, muzzle, quadMult);
    }
    // tiny camera kick
    this.cameraKick = (this.cameraKick || 0) + 0.02 * (w.kick || 1);
  }

  hitscan(origin, dir, range, damage, owner, weaponId, strong) {
    const wall = this.world.raycast(origin, dir, range);
    let wallDist = wall ? wall.distance : range;
    let point = wall ? wall.point.clone() : origin.clone().addScaledVector(dir, range);
    let closest = null, closestDist = wallDist;
    for (const e of this.combatants) {
      if (e === owner || !e.alive) continue;
      const center = this.entityCenter(e);
      const t = this.raySphere(origin, dir, center, e.isPlayer ? 0.62 : 0.82);
      if (t !== null && t < closestDist) {
        closestDist = t;
        closest = e;
        point = origin.clone().addScaledVector(dir, t);
      }
    }
    if (closest) {
      closest.hurt(damage, owner, this, weaponId);
      this.effects.spark(point, dir.clone().negate(), weaponId === 'rail' ? 0x99fbff : 0xffc080, strong ? 16 : 6);
      this.audio.hit();
    } else if (wall) {
      const n = wall.face ? wall.face.normal.clone().transformDirection(wall.object.matrixWorld) : dir.clone().negate();
      this.effects.spark(point, n, 0xffc080, 5);
    }
    return { point, target: closest };
  }

  spawnProjectile(owner, w, origin, forward, muzzle, quadMult) {
    const isRocket = w.id === 'rocket';
    const g = new THREE.Group();
    if (isRocket) {
      const body = new THREE.Mesh(new THREE.CylinderGeometry(0.11, 0.15, 0.6, 10), this.projectileMats.rocket);
      body.rotation.x = Math.PI / 2;
      const tip = new THREE.Mesh(new THREE.ConeGeometry(0.16, 0.28, 10), new THREE.MeshBasicMaterial({ color: 0xfff0c0 }));
      tip.rotation.x = -Math.PI / 2;
      tip.position.z = -0.42;
      const ring = new THREE.Mesh(new THREE.TorusGeometry(0.16, 0.025, 4, 14), new THREE.MeshBasicMaterial({ color: 0xff6a00 }));
      ring.position.z = 0.1;
      g.add(body, tip, ring);
    } else {
      const disc = new THREE.Mesh(new THREE.CylinderGeometry(0.26, 0.26, 0.055, 20), this.projectileMats.spin);
      disc.rotation.x = Math.PI / 2;
      const rim = new THREE.Mesh(new THREE.TorusGeometry(0.27, 0.03, 4, 22), new THREE.MeshBasicMaterial({ color: 0xbefaff }));
      g.add(disc, rim);
    }
    const glow = new THREE.Sprite(new THREE.SpriteMaterial({
      map: isRocket ? this.projectileMats.rocketGlow : this.projectileMats.spinGlow,
      color: isRocket ? 0xffb060 : 0x66ddff,
      transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false
    }));
    glow.scale.setScalar(isRocket ? 2.6 : 1.8);
    g.add(glow);
    const start = origin.clone().addScaledVector(forward, 0.85);
    if (this.world.collideSphere(start, 0.2)) start.copy(origin).addScaledVector(forward, 0.35);
    g.position.copy(start);
    this.scene.add(g);
    const proj = {
      owner, weapon: w, pos: start.clone(), prev: start.clone(),
      vel: forward.clone().multiplyScalar(w.speed),
      gravity: isRocket ? 1.1 : 2.0,
      damage: w.damage * quadMult, splash: w.splash * quadMult, radius: w.splashRadius,
      life: 6, mesh: g, type: isRocket ? 'rocket' : 'spin',
      trailTimer: 0, directHit: null,
    };
    this.projectiles.push(proj);
  }

  botFire(bot, dir, dist) {
    const origin = bot.eyePosition;
    const start = origin.clone().addScaledVector(dir, 0.9);
    const g = new THREE.Group();
    const orb = new THREE.Mesh(new THREE.SphereGeometry(0.16, 10, 8), new THREE.MeshBasicMaterial({ color: bot.color }));
    const ring = new THREE.Mesh(new THREE.TorusGeometry(0.24, 0.03, 4, 14), new THREE.MeshBasicMaterial({ color: bot.color, transparent: true, opacity: 0.8 }));
    g.add(orb, ring);
    const glow = new THREE.Sprite(new THREE.SpriteMaterial({
      map: this.projectileMats.spinGlow, color: bot.color, transparent: true, opacity: 0.8, blending: THREE.AdditiveBlending, depthWrite: false
    }));
    glow.scale.setScalar(1.7);
    g.add(glow);
    g.position.copy(start);
    this.scene.add(g);
    const proj = {
      owner: bot, weapon: null, pos: start.clone(), prev: start.clone(),
      vel: dir.clone().multiplyScalar(40),
      gravity: 3.4,
      damage: 22, splash: 20, radius: 3.1,
      life: 5, mesh: g, type: 'bot', color: bot.color,
      trailTimer: 0, directHit: null,
    };
    this.projectiles.push(proj);
    this.audio.tone({ f: 760, to: 300, dur: 0.18, type: 'triangle', vol: 0.035, filter: { f: 2200, to: 600, q: 2 } });
  }

  updateProjectiles(dt) {
    for (let i = this.projectiles.length - 1; i >= 0; i--) {
      const p = this.projectiles[i];
      p.life -= dt;
      if (p.life <= 0) { this.removeProjectile(p); this.projectiles.splice(i, 1); continue; }
      p.prev.copy(p.pos);
      p.vel.y -= p.gravity * dt;
      const speed = p.vel.length();
      const steps = Math.max(1, Math.ceil(speed * dt / 0.45));
      let exploded = false;
      for (let s = 0; s < steps; s++) {
        p.pos.addScaledVector(p.vel, dt / steps);
        // world
        if (this.world.collideSphere(p.pos, 0.18)) {
          this.explodeProjectile(p, p.pos.clone());
          exploded = true;
          break;
        }
        // entities
        for (const e of this.combatants) {
          if (!e.alive || e === p.owner) continue;
          const c = this.entityCenter(e);
          const r = e.isPlayer ? 0.75 : 0.95;
          if (p.pos.distanceToSquared(c) < r * r) {
            p.directHit = e;
            this.explodeProjectile(p, p.pos.clone());
            exploded = true;
            break;
          }
        }
        if (exploded) break;
      }
      if (exploded) {
        this.removeProjectile(p);
        this.projectiles.splice(i, 1);
        continue;
      }
      p.mesh.position.copy(p.pos);
      p.mesh.lookAt(p.pos.clone().add(p.vel));
      if (p.type === 'spin') p.mesh.rotation.z += dt * 22;
      // trail
      p.trailTimer -= dt;
      if (p.trailTimer <= 0) {
        p.trailTimer = 0.025;
        const isBot = p.type === 'bot';
        this.effects.particle({
          x: p.pos.x + (Math.random() - 0.5) * 0.2, y: p.pos.y + (Math.random() - 0.5) * 0.2, z: p.pos.z + (Math.random() - 0.5) * 0.2,
          vx: (Math.random() - 0.5) * 0.4, vy: (Math.random() - 0.5) * 0.4, vz: (Math.random() - 0.5) * 0.4,
          r: isBot ? ((p.color >> 16) & 255) / 255 : 1,
          g: isBot ? ((p.color >> 8) & 255) / 255 : 0.65,
          b: isBot ? (p.color & 255) / 255 : 0.3,
          size: isBot ? 0.18 : 0.24, life: isBot ? 0.3 : 0.55, grav: -1, drag: 2
        });
      }
    }
  }

  removeProjectile(p) {
    this.scene.remove(p.mesh);
    p.mesh.traverse(o => { if (o.isMesh) { o.geometry.dispose(); if (o.material.dispose) o.material.dispose(); } });
  }

  explodeProjectile(p, pos) {
    const big = p.type === 'rocket' ? 1.5 : p.type === 'spin' ? 1.1 : 0.85;
    this.effects.explosion(pos, big);
    this.audio.explosion(big);
    const owner = p.owner;
    if (p.directHit) {
      let dmg = p.damage * (owner && owner.quad > 0 ? 1 : 1);
      p.directHit.hurt(dmg, owner, this, p.type === 'rocket' ? 'rocket' : p.type === 'spin' ? 'spin' : 'plasma');
      if (owner && owner.isPlayer) this.hud.hitmarker(false);
    }
    // splash + knockback
    for (const e of this.combatants) {
      if (!e.alive) continue;
      const c = this.entityCenter(e);
      const d = c.distanceTo(pos);
      if (d > p.radius + 0.8) continue;
      const falloff = Math.max(0, 1 - d / p.radius);
      const self = e === owner;
      let dmg = p.splash * (0.35 + 0.65 * falloff);
      if (self) dmg *= 0.42;
      if (dmg > 1) e.hurt(dmg, owner, this, p.type === 'bot' ? 'plasma' : p.type);
      // knockback
      const dir = c.clone().sub(pos);
      if (dir.lengthSq() < 0.01) dir.set(0, 1, 0);
      dir.normalize();
      const power = (p.type === 'rocket' ? 8.6 : p.type === 'spin' ? 6.4 : 4.6) * (0.35 + falloff) * (self ? 1.35 : 1);
      e.velocity.x += dir.x * power;
      e.velocity.z += dir.z * power;
      e.velocity.y += Math.max(2.5, dir.y * power + (self ? 8.2 : 3.4) * falloff);
      if (e.isPlayer) {
        this.shake = Math.min(1.2, this.shake + falloff * (self ? 0.8 : 0.55));
      }
    }
  }

  collectPickup(p, entity) {
    if (!p.active) return;
    const isPlayer = entity.isPlayer;
    let msg = '';
    if (p.type === 'health') {
      if (entity.health >= entity.maxHealth) return;
      entity.addHealth(25);
      msg = '+25 HEALTH';
    } else if (p.type === 'mega') {
      if (entity.health >= entity.maxHealth) return;
      entity.addHealth(100);
      msg = 'MEGA HEALTH';
    } else if (p.type === 'armor') {
      if (entity.armor >= 150) return;
      entity.addArmor(50);
      msg = '+50 ARMOR';
    } else if (p.type === 'rockets') {
      if (!isPlayer) return;
      if (entity.ammo.rocket >= 12) return;
      entity.ammo.rocket = Math.min(12, entity.ammo.rocket + 4);
      msg = '+4 ROCKETS';
    } else if (p.type === 'rails') {
      if (!isPlayer) return;
      if (entity.ammo.rail >= 10) return;
      entity.ammo.rail = Math.min(10, entity.ammo.rail + 3);
      msg = '+3 RAIL SLUGS';
    } else if (p.type === 'discs') {
      if (!isPlayer) return;
      if (entity.ammo.spin >= 10) return;
      entity.ammo.spin = Math.min(10, entity.ammo.spin + 3);
      msg = '+3 SPINFUSOR DISCS';
    } else if (p.type === 'quad') {
      if (!isPlayer) return;
      entity.quad = 30;
      msg = 'QUAD DAMAGE';
      this.hud.announce('QUAD DAMAGE', 'gold', 2400);
      this.hud.toast('QUAD DAMAGE — 4× OUTPUT FOR 30s');
      this.audio.quad();
      this.quadWasActive = true;
    }
    p.active = false;
    p.timer = p.respawn;
    p.group.visible = false;
    this.effects.burst(p.position.clone(), 16, {
      color: p.type === 'health' || p.type === 'mega' ? 0xff5c7a : p.type === 'quad' ? 0xffb02e : p.type === 'armor' ? 0x51ffb0 : 0x7de8ff,
      speed: 5, size: 0.2, life: 0.5, grav: 2
    });
    if (isPlayer) {
      this.audio[p.type === 'health' || p.type === 'mega' ? 'pickup' : p.type === 'armor' ? 'armor' : 'pickup']();
      this.hud.toast(msg);
      if (p.type !== 'quad') this.hud.hitmarker(false);
    }
  }

  // ---------------- match flow ----------------
  kill(victim, source, cause = 'fragged') {
    if (!victim.alive) return;
    victim.alive = false;
    victim.health = 0;
    victim.deaths++;
    victim.streak = 0;
    victim.quad = 0;
    if (victim.isPlayer) {
      victim.deathCause = cause;
      victim.killerName = source ? source.name : 'THE VOID';
      this.playerKills = [];
      this.respawnTimer = 3.0;
      this.deathCam = 0;
      this.hud.showRespawn(source ? source.name : null, cause);
      this.audio.death();
      this.hud.announce('YOU WERE FRIED', 'danger', 2000);
      this.viewModel.scene.visible = false;
      this.audio.setJet(false);
    } else {
      victim.model.visible = false;
      victim.respawnTimer = 3.2 + Math.random() * 1.2;
      victim.killerName = source ? source.name : 'THE VOID';
      this.effects.gibs(victim.position.clone().setY(victim.position.y + 1.1), victim.color, victim.velocity.clone().normalize());
      this.effects.explosion(victim.position.clone().setY(victim.position.y + 1.0), 0.8);
      this.audio.explosion(0.8);
    }

    let killerName = source ? source.name : 'THE VOID';
    if (source && source !== victim) {
      source.score++;
      source.streak++;
      source.bestStreak = Math.max(source.bestStreak || 0, source.streak);
      if (source.isPlayer) {
        this.hud.hitmarker(true);
        this.audio.hitKill();
        this.playerKills.push(this.time);
        this.playerKills = this.playerKills.filter(t => this.time - t < 4);
        const n = this.playerKills.length;
        if (n >= 2) {
          const names = ['', '', 'DOUBLE KILL', 'MULTI KILL', 'MEGA KILL', 'MONSTER KILL'];
          this.hud.announce(names[Math.min(5, n)], 'gold', 1700);
        }
        if (source.streak === 3) this.hud.announce('KILLING SPREE', '', 1800);
        if (source.streak === 5) this.hud.announce('RAMPAGE', 'gold', 1900);
        if (source.streak === 8) this.hud.announce('UNSTOPPABLE', 'gold', 2000);
      }
    } else if (source === victim) {
      victim.score = Math.max(0, victim.score - 1);
      killerName = victim.name;
    }

    if (this.firstBlood) {
      this.firstBlood = false;
      this.hud.announce('FIRST BLOOD', 'danger', 1600);
    }
    this.hud.killfeed(killerName, victim.name, cause, victim.quad > 0 || (source && source.quad > 0));

    // check frag limit
    const maxScore = Math.max(...this.combatants.map(e => e.score));
    if (maxScore >= this.fragLimit && !this.over) {
      this.endMatch(this.player.score >= this.fragLimit || this.player.score >= maxScore);
    }
  }

  endMatch(victory) {
    if (this.over) return;
    this.over = true;
    this.state = 'gameover';
    this.input.enabled = false;
    this.input.releaseLock();
    this.audio.setJet(false);
    this.audio.setIntensity(0.25);
    this.audio.matchEnd(victory);
    this.hud.setVisible(false);
    this.hud.hideRespawn();
    this.hud.toggleScoreboard(false);
    this.viewModel.scene.visible = false;
    this.hud.showGameOver(this, victory);
  }

  respawnPlayer() {
    // pick spawn farthest from living bots
    let best = this.world.spawnPoints[0], bestScore = -Infinity;
    for (const sp of this.world.spawnPoints) {
      let closest = Infinity;
      for (const b of this.bots) if (b.alive) closest = Math.min(closest, sp.pos.distanceTo(b.position));
      if (closest > bestScore) { bestScore = closest; best = sp; }
    }
    this.player.spawn(this.world, best);
    this.player.alive = true;
    this.player.protection = 1.8;
    this.respawnTimer = 0;
    this.deathCam = 0;
    this.viewModel.scene.visible = true;
    this.viewModel.show(0, true);
    this.hud.hideRespawn();
    this.effects.burst(this.player.position.clone().setY(this.player.position.y + 0.5), 28, {
      color: 0x66f0ff, speed: 6, size: 0.26, life: 0.8, grav: 1
    });
    this.audio.spawn();
    this.hud.announce('REDEPLOYED', '', 1400);
    if (!this.input.isTouch) this.hud.showPointerHint(!this.input.locked);
  }

  respawnBot(bot) {
    const player = this.player;
    const sorted = [...this.world.spawnPoints].sort((a, b) => b.pos.distanceTo(player.position) - a.pos.distanceTo(player.position));
    const sp = sorted[Math.floor(Math.random() * Math.min(5, sorted.length))];
    bot.spawn(this.world, sp);
    bot.tag.material.opacity = 0.9;
    this.spawnFlash(bot.position, bot.color);
  }

  // ---------------- frame ----------------
  frame(dt) {
    this.time += dt;
    if (this.state === 'playing') this.updatePlaying(dt);
    else if (this.state === 'paused') {
      // keep subtle ambience alive but freeze the simulation
    } else if (this.state === 'menu') {
      this.updateMenu(dt);
    } else if (this.state === 'gameover') {
      this.world.update(dt, this.time);
      this.effects.update(dt, this.time);
    }
    if (this.audio.ctx) this.audio.update();
    this.render();
    this.input.endFrame();
  }

  updateMenu(dt) {
    this.menuAngle += dt * 0.045;
    const a = this.menuAngle;
    const r = 36;
    this.camera.position.set(Math.cos(a) * r, 16 + Math.sin(this.time * 0.3) * 1.8, Math.sin(a) * r);
    this.camera.lookAt(0, 5.2, 0);
    this.camera.rotation.z = Math.sin(this.time * 0.2) * 0.01;
    this.world.update(dt, this.time);
    this.effects.update(dt, this.time);
    this.bots.forEach((b, i) => {
      if (!b.model.visible) return;
      b.model.position.y = 0.02 + Math.sin(this.time * 1.4 + i) * 0.02;
      b.bodyGroup.rotation.y = Math.sin(this.time * 0.7 + i) * 0.15;
      b.tag.material.opacity = 0;
    });
  }

  updatePlaying(dt) {
    // timers
    if (!this.over) {
      this.timeLeft -= dt;
      if (this.timeLeft <= 0) {
        this.timeLeft = 0;
        const sorted = [...this.combatants].sort((a, b) => b.score - a.score);
        this.endMatch(sorted[0] && sorted[0].isPlayer);
        return;
      }
    }
    this.recoil = Math.max(0, this.recoil - dt * 5);
    this.shake = Math.max(0, this.shake - dt * 3.2);
    this.cameraKick = Math.max(0, (this.cameraKick || 0) - dt * 4);
    this.pointerHintTimer = Math.max(0, this.pointerHintTimer - dt);
    if (this.pointerHintTimer <= 0 && this.input.locked) this.hud.showPointerHint(false);

    if (this.player.alive) {
      this.player.update(dt, this.input, this.world, this, this.camera);
      // void death
      if (this.player.position.y < -20) this.kill(this.player, null, 'void');
    }
    // bots
    for (const b of this.bots) {
      if (b.alive) {
        b.update(dt, this);
      } else {
        b.respawnTimer -= dt;
        if (b.respawnTimer <= 0) this.respawnBot(b);
      }
    }
    // player respawn
    if (!this.player.alive) {
      this.respawnTimer -= dt;
      this.deathCam += dt;
      this.updateDeathCamera(dt);
      if (this.respawnTimer <= 0) this.respawnPlayer();
    }

    this.updateProjectiles(dt);
    this.world.update(dt, this.time);
    this.effects.update(dt, this.time);

    // quad expiry
    const quadNow = this.player.quad > 0;
    if (this.quadWasActive && !quadNow) {
      this.quadWasActive = false;
      this.hud.announce('QUAD EXPIRED', '', 1200);
    }

    // camera shake / recoil
    if (this.player.alive) {
      this.camera.rotation.x += (this.recoil * 0.008) + (this.cameraKick || 0) * 0.02;
      if (!this.reducedMotion) {
        this.camera.position.x += (Math.random() - 0.5) * this.shake * 0.06;
        this.camera.position.y += (Math.random() - 0.5) * this.shake * 0.06;
        this.camera.rotation.z += (Math.random() - 0.5) * this.shake * 0.008;
      }
    }

    // aim target + HUD
    this.aimTarget = this.findAimTarget();
    this.hud.update(dt, this);

    // scoreboard
    const showTab = this.input.isDown('Tab');
    if (showTab !== this.lastTab) {
      this.lastTab = showTab;
      this.hud.toggleScoreboard(showTab);
    }
    if (this.input.wasPressed('KeyM')) {
      this.audio.init();
      this.audio.setMuted(!this.audio.muted);
      this.hud.toast(this.audio.muted ? 'AUDIO MUTED' : 'AUDIO ONLINE');
      $('soundBtn').textContent = 'SOUND: ' + (this.audio.muted ? 'OFF' : 'ON');
      $('pauseSoundBtn').textContent = 'SOUND: ' + (this.audio.muted ? 'OFF' : 'ON');
    }
    if (this.input.wasPressed('KeyV')) {
      this.reducedMotion = !this.reducedMotion;
      this.hud.toast(this.reducedMotion ? 'REDUCED MOTION ON' : 'REDUCED MOTION OFF');
    }

    // pointer hint
    if (!this.input.isTouch && !this.input.locked && this.player.alive) {
      this.hud.showPointerHint(true);
    } else {
      this.hud.showPointerHint(false);
    }

    // viewmodel
    if (this.player.alive) {
      this.viewModel.scene.visible = true;
      this.viewModel.update(dt, {
        moving: Math.hypot(this.player.velocity.x, this.player.velocity.z) > 1 ? 1 : 0,
        grounded: this.player.grounded,
        speed: Math.hypot(this.player.velocity.x, this.player.velocity.z),
        lookX: this.player.lastLook.x,
        lookY: this.player.lastLook.y,
        time: this.time
      });
    } else {
      this.viewModel.scene.visible = false;
    }

    // music intensity
    this.audio.setIntensity(this.player.alive ? Math.min(1, 0.55 + this.player.streak * 0.05) : 0.35);
  }

  updateDeathCamera(dt) {
    const k = Math.min(1, this.deathCam * 1.6);
    const eye = this.player.eyePosition;
    this.camera.position.set(eye.x, eye.y - k * 1.1 + this.deathCam * 0.05, eye.z);
    this.camera.rotation.order = 'YXZ';
    this.camera.rotation.y = this.player.yaw + Math.sin(this.deathCam * 0.8) * 0.15 * k;
    this.camera.rotation.x = this.player.pitch - k * 0.45;
    this.camera.rotation.z = k * 0.55;
  }

  findAimTarget() {
    if (!this.player.alive) return null;
    const origin = this.player.eyePosition;
    const dir = this.player.forward;
    const wall = this.world.raycast(origin, dir, 120);
    const maxT = wall ? wall.distance : 120;
    let best = null, bestT = maxT;
    for (const b of this.bots) {
      if (!b.alive) continue;
      const t = this.raySphere(origin, dir, this.entityCenter(b), 0.9);
      if (t !== null && t < bestT) { bestT = t; best = b; }
    }
    return best;
  }

  render() {
    const r = this.renderer;
    r.clear();
    r.render(this.scene, this.camera);
    if (this.viewModel.scene.visible && this.state === 'playing' && this.player.alive) {
      r.clearDepth();
      r.render(this.viewModel.scene, this.viewModel.camera);
    }
  }
}

const game = new Game();
window.__game = game;
let last = performance.now();
function loop(now) {
  let dt = (now - last) / 1000;
  last = now;
  if (!Number.isFinite(dt) || dt <= 0) dt = 1 / 60;
  dt = Math.min(dt, 0.05);
  game.frame(dt);
  requestAnimationFrame(loop);
}
requestAnimationFrame(loop);

